function missingFields(p){const missing=[];const stocks=S.stocks.filter(s=>s.partId===p.id&&s.qty>0);if(!stocks.length||stocks.every(s=>!s.bin))missing.push('库位');if(!p.lcscCode)missing.push('立创编号');if(!p.package)missing.push('封装');const by={电容:[['value','容量'],['voltage','耐压'],['dielectric','介质'],['tolerance','精度']],电阻:[['value','阻值'],['power','功率'],['tolerance','精度'],['tcr','温度系数']],MOS管:[['polarity','沟道'],['voltage','耐压'],['rdson','RDS(on)'],['vgs','测试条件']],IC:[['manufacturer','制造商'],['package','封装'],['datasheetUrl','官方资料'],['lcscCode','立创编号']]};for(const [key,label] of by[p.category]||[])if(!p[key]&&!missing.includes(label))missing.push(label);return missing;}
