function setConnection(ok){online=ok;const target=isLocal?'本机服务':'远程库存';$('#connectionStatus').innerHTML=`<span class="online-dot ${ok?'':'offline'}"></span>${ok?'已连接'+target:'离线快照'}`;$('#saveState').innerHTML=`<span class="online-dot ${ok?'':'offline'}"></span>${ok?(isLocal?'库存已保存在电脑':'已读取电脑最新库存'):'等待重新连接'}`;$('#offlineBanner').hidden=ok;}
function acceptState(s){S=s;localStorage.setItem(cacheKey('cache'),JSON.stringify(s));}
function cacheKey(kind){return 'team-v2-'+(T.user?.id||'none')+'-'+space+'-'+kind;}
async function api(endpoint,{method='GET',body,auth=false,workspace=space}={}){
  const epoch=T.epoch,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),method==='GET'?8000:65000);let response;
  try{response=await fetch('/api/'+endpoint,{method,headers:{'Content-Type':'application/json','X-Workspace':workspace},signal:controller.signal,...(body!==undefined?{body:JSON.stringify(body)}:{})});}
  catch{if(epoch===T.epoch)setConnection(false);throw Object.assign(new Error('暂时无法连接电脑服务'),{network:true});}finally{clearTimeout(timer);}
  const data=await response.json();if(epoch!==T.epoch)throw new Error('元件库已切换，请在当前库重新操作');
  if(!response.ok){if(response.status===401&&!auth){clearIdentity();showAuthScreen('登录已失效，请重新登录');}if(response.status===403&&!auth){purgeCache(space);S=null;eventStream?.close();$('#page').innerHTML='<div class="panel"><h2>当前权限已变化</h2><p>请重新选择你有权访问的元件库。</p><button class="btn" data-act="team-switch">选择元件库</button></div>';closeModal();}throw Object.assign(new Error(data.error||'操作未完成'),{status:response.status});}
  if(!auth)setConnection(true);return data;
}
async function load(redraw=true){if(!T.user)throw new Error('请先登录');const r=await api('state');currentRole=r.role;acceptState(r.state);isLocal=r.local;remoteAccess=r.remoteAccess;const i=T.workspaces.findIndex(x=>x.id===space);if(i>=0)T.workspaces[i]=r.workspace;setConnection(true);if(redraw)render();return r;}
function connectEvents(){eventStream?.close();if(!T.user||!('EventSource' in window)||!online)return;const epoch=T.epoch;eventStream=new EventSource('/api/events?workspace='+encodeURIComponent(space));eventStream.onmessage=async e=>{if(epoch!==T.epoch)return;try{const incoming=JSON.parse(e.data);if(incoming.revision!==T.team?.revision){await refreshIdentity();if(epoch!==T.epoch)return;}if(!S||incoming.rev!==S.rev){if($('#dialog').open){toast('库存已被其他成员更新，提交时会再次核对');return;}await load();}if(view==='team'&&!$('#dialog').open){await teamLoad();render();}}catch{}};eventStream.addEventListener('revoked',async()=>{eventStream?.close();purgeCache(space);S=null;closeModal();try{await refreshIdentity();await switchWorkspace(T.workspaces[0]?.id);}catch{clearIdentity();showAuthScreen('设备或库权限已失效，请重新登录');}});}
async function mutate(action,requestId){if(!online)throw new Error('当前离线，请保存草稿后联网提交');const r=await api('action',{method:'POST',body:{...action,rev:S.rev,requestId:requestId||uid()}});acceptState(r.state);render();if(r.pending){closeModal();throw new Error('已提交管理员审批，库存尚未改变；请到成员与协作查看进度');}return r;}
