function dashboard(){const stocks=S.stocks.filter(st=>!loc||st.locationId===loc),alerts=collectAlerts(S),low=S.parts.filter(p=>p.minStock>total(p.id));const recentIds=[...new Set(S.orders.slice().reverse().flatMap(o=>o.lines.map(l=>l.stockId)))],recent=[...recentIds.map(id=>stocks.find(s=>s.id===id)).filter(Boolean),...stocks.filter(s=>!recentIds.includes(s.id))].slice(0,5);const orders=S.orders.slice(-4).reverse();const date=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});
return `${header(date,'每一颗元件，都有归处。','从一颗电阻，到下一块电路板。',button(icon('plus')+' 入库','in',true)+button(icon('minus')+' 出库','out'))}
<div class="stats-grid">${[['库存总量',num(stocks.reduce((n,x)=>n+x.qty,0)),'个 · 当前地点','box','teal'],['元件种类',num(new Set(stocks.map(x=>x.partId)).size),'种 · 每种规格独立编号','chip',''],['需要补货',num(low.length),'种 · 低于安全库存','bell',''],['存放地点',num(S.locations.length),'处 · 支持细分到抽屉、元件盒','pin','']].map(([label,value,foot,ic,cls])=>`<div class="stat-card ${cls}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ic)}</span></div><strong>${value}</strong><div class="stat-foot">${foot}</div></div>`).join('')}</div>
<div class="section-grid"><section class="panel inventory-preview"><div class="panel-head"><div><h2>最近使用与库存</h2><p>先显示最近出入库的元件，拿取时少找一步。</p></div><button class="text-btn" data-view="inventory">全部元件 →</button></div>${locationPills()}${recent.length?`<div class="mini-table">${recent.map(st=>{const p=part(st.partId);return `<button class="mini-row" data-act="detail" data-id="${p.id}"><div class="part-icon ${p.category==='电容'?'cap':p.category==='电阻'?'res':'ic'}">${icon(p.category==='IC'?'chip':'box')}</div><div class="part-name">${esc(p.name)}<small>${esc(p.package||'未填封装')} · ${esc(spec(p))}</small></div><div class="location-label">${esc(locationName(st.locationId))}<small>${esc(st.bin||'未分配库位')}</small></div><span class="qty">${num(st.qty)}<small>个</small></span></button>`;}).join('')}</div>`:empty('从第一颗元件开始','手动输入，或拍下包装标签。确认后就能找到它。',button(icon('plus')+' 添加第一种元件','add-part',true))}</section>
  <section class="panel quick-panel"><div class="panel-head"><div><h2>快捷操作</h2><p>手机上优先显示找料和快速记账。</p></div></div><div class="quick-grid">${[['camera','orange','扫一扫 / 拍标签','查元件、盒子或识别入库','scan-hub'],['minus','green','快速领用','离线时保存待同步草稿','out'],['bom','blue','项目齐料','算可做板数和缺料','projects-view'],['flow','purple',`待同步 ${drafts().length} 笔`,'联网后核对再提交','drafts-view']].map(([ic,c,t,d,a])=>`<button class="quick-action" data-act="${a}"><span class="quick-icon ${c}">${icon(ic)}</span><span><b>${t}</b><small>${d}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="tip-card">${icon('shield')}<div><b>确认库存与草稿分开显示</b><p>${online?'已连接电脑库存。':'当前为离线快照；临时领用只会保存为草稿。'}</p></div></div></section></div>
<div class="section-grid lower"><section class="panel activity-panel"><div class="panel-head"><div><h2>最近出入库</h2><p>采购、用料与损耗都可以追溯。</p></div><button class="text-btn" data-view="transactions">查看记录 →</button></div>${orders.length?`<div class="activity-list">${orders.map(o=>`<button class="activity-row" data-act="order-detail" data-id="${o.id}"><span class="activity-icon ${o.type==='入库'?'in':'out'}">${icon(o.type==='入库'?'plus':'minus')}</span><div><b>${esc(o.source)} · ${o.type}${o.undoneBy?' · 已撤销':''}</b><p>${esc(o.note||part(S.stocks.find(s=>s.id===o.lines[0]?.stockId)?.partId)?.name||'库存变更')}</p></div><time>${time(o.time)}</time></button>`).join('')}</div>`:empty('还没有流水','完成第一笔出入库后，会自动出现在这里。')}</section><section class="panel alert-panel"><div class="panel-head"><div><h2>需要关注</h2><p>库存提醒与有来源的价格、生命周期消息。</p></div><button class="text-btn" data-view="alerts">全部提醒 →</button></div>${alerts.length?`<div class="alert-list">${alerts.slice(0,3).map(a=>`<button class="alert-row" data-act="detail" data-id="${a.partId}"><span class="alert-dot ${a.level==='danger'?'red':'amber'}"></span><div><b>${esc(a.title)}</b><p>${esc(a.body)}</p></div></button>`).join('')}</div>`:empty('目前没有待处理提醒',S.settings.feedEnabled?'可在元件详情中添加关注。':'联网行情尚未接入；安全库存提醒已可用。')}</section></div>`;}
function inventoryCurrentStocks(){const query=filter.q.trim();return S.stocks.filter(st=>{const p=part(st.partId);return (!loc||loc===st.locationId)&&(!filter.category||filter.category===p.category)&&(!filter.mount||filter.mount===p.mount)&&(!filter.low||total(p.id)<p.minStock)&&matchesPartQuery(p,st,locationName(st.locationId),query);});}
function inventory(){const rows=inventoryCurrentStocks(),allSelected=rows.length>0&&rows.every(st=>inventorySelected.has(st.id));return `${header('INVENTORY','元件库','搜索理解常见电气单位，100nF 与 0.1μF、4K7 与 4.7kΩ 可以互相找到。',button('批量整理','organize-view')+button('元件盒与二维码','storage-view')+button(icon('download')+' 一键导出全部','export-inventory')+button(icon('plus')+' 新增元件','add-part',true))}<div class="toolbar"><div class="search-box">${icon('search')}<input id="inventorySearch" aria-label="搜索元件" placeholder="搜索型号、0.1μF、4K7、0603、库位…" value="${esc(filter.q)}"></div><select id="categoryFilter" aria-label="分类"><option value="">全部分类</option>${CATEGORIES.map(c=>`<option ${filter.category===c?'selected':''}>${c}</option>`).join('')}</select><select id="mountFilter" aria-label="贴装方式"><option value="">贴片 + 插件</option>${['贴片','插件'].map(c=>`<option ${filter.mount===c?'selected':''}>${c}</option>`).join('')}</select><label class="check-pill"><input id="lowFilter" type="checkbox" ${filter.low?'checked':''}>仅看缺料</label><label class="check-pill"><input id="inventorySelectAll" type="checkbox" ${allSelected?'checked':''}><span id="inventorySelectLabel">全选当前结果（${rows.length}）</span></label>${inventorySelected.size?button(`导出已选 ${inventorySelected.size} 项`,'export-inventory-selected')+button(`批量出库已选 ${inventorySelected.size} 项`,'bulk-stock-out',true)+button('清空选择','inventory-clear'):''}</div>${locationPills()}<div class="panel table-panel"><div class="table-scroll"><table class="inventory-table"><thead><tr><th><input class="inventory-select-all" type="checkbox" aria-label="全选当前库存" ${allSelected?'checked':''}></th><th>元件 / 规格</th><th>分类与封装</th><th>存放位置</th><th class="align-right">数量</th><th>可用 / 状态</th><th>操作</th></tr></thead><tbody id="inventoryBody">${inventoryRows()}</tbody></table></div></div><p class="page-hint">可用数量已扣除项目预留；实物库存只在实际领料出库时扣减。批量出库会把选中库位当前数量一次性扣到 0，提交前会弹窗复核。</p>`;}
  function inventoryRows(){const rows=inventoryCurrentStocks();return rows.length?rows.map(st=>{const p=part(st.partId),low=total(p.id)<p.minStock,available=Math.max(0,total(p.id)-reserved(p.id));return `<tr><td><input class="inventory-check" type="checkbox" data-id="${st.id}" aria-label="选择 ${esc(p.sku)}" ${inventorySelected.has(st.id)?'checked':''}></td><td><button class="part-cell cell-button" data-act="detail" data-id="${p.id}"><b>${esc(p.name)}</b><span>${esc(p.sku)}${p.value?' · '+esc(spec(p)):''}</span></button></td><td><span class="category-badge cat-${CATEGORIES.indexOf(p.category)}">${p.category}</span><small class="cell-sub">${p.mount} · ${esc(p.package||'—')}</small></td><td><b>${esc(locationName(st.locationId))}</b><small class="cell-sub">${esc(st.bin||'未分配库位')}</small></td><td class="align-right"><strong class="quantity-number">${num(st.qty)}</strong><small class="cell-sub">个</small></td><td><b>${num(available)} 可用</b><small class="cell-sub">${reserved(p.id)?`已预留 ${num(reserved(p.id))}`:low?'需要补货':'库存正常'}</small></td><td><div class="row-actions"><button class="text-btn" data-act="stock-in" data-id="${st.id}">入库</button><button class="text-btn" data-act="stock-out" data-id="${st.id}">出库</button></div></td></tr>`;}).join(''):`<tr><td colspan="7">${empty('没有找到匹配的元件',S.parts.length?'换个关键词或地点试试。':'点击“新增元件”建立你的第一条库存。')}</td></tr>`;}
function organizeKeyFields(p){const map={电容:[['value','容量'],['voltage','耐压'],['dielectric','介质'],['tolerance','精度%']],电阻:[['value','阻值'],['power','功率'],['tolerance','精度%'],['tcr','温漂']],电感:[['value','电感量'],['current','电流'],['tolerance','精度%'],['frequency','频率']],MOS管:[['polarity','沟道'],['voltage','耐压'],['rdson','RDS(on)'],['vgs','测试条件']],IC:[['manufacturer','制造商'],['function','功能'],['pins','引脚'],['interface','接口']]};return map[p.category]||[['value','主要参数'],['voltage','耐压'],['current','电流'],['type','类型']];}
function organizeRows(){let rows=S.parts.filter(p=>(!organize.pending||missingFields(p).length)&&(!organize.q||matchesPartQuery(p,primaryStock(p.id),locationName(primaryStock(p.id)?.locationId),organize.q)));return rows.map(p=>{const st=primaryStock(p.id),missing=missingFields(p),keys=organizeKeyFields(p);return `<tr data-organize-row="${p.id}" data-stock-id="${st?.id||''}"><td><input class="organize-check" type="checkbox" data-id="${p.id}" ${organize.selected.has(p.id)?'checked':''}></td><td><button class="cell-button part-cell" data-act="detail" data-id="${p.id}"><b>${esc(p.sku)}</b><span>${missing.length?`待完善：${esc(missing.join('、'))}`:'资料完整'}</span></button></td><td><select data-field="category">${CATEGORIES.map(x=>`<option ${x===p.category?'selected':''}>${x}</option>`).join('')}</select></td><td><input data-field="package" value="${esc(p.package)}" placeholder="封装"></td><td><div class="organize-keys">${keys.map(([key,label])=>`<label>${label}<input data-field="${key}" value="${esc(p[key]||'')}"></label>`).join('')}</div></td><td><input data-field="manufacturer" value="${esc(p.manufacturer)}" placeholder="制造商"><input data-field="lcscCode" value="${esc(p.lcscCode)}" placeholder="C编号"></td><td><select data-stock-field="locationId"><option value="">无库存库位</option>${S.locations.map(l=>`<option value="${l.id}" ${l.id===st?.locationId?'selected':''}>${esc(l.name)}</option>`).join('')}</select><input data-stock-field="bin" value="${esc(st?.bin||'')}" placeholder="抽屉 / 格位"></td><td><input data-field="minStock" type="number" min="0" value="${p.minStock}"></td></tr>`;}).join('')||`<tr><td colspan="8">${empty('当前没有待完善项','切换为“全部元件”可以继续批量修改。')}</td></tr>`;}
function organizeCurrentIds(){return S.parts.filter(p=>(!organize.pending||missingFields(p).length)&&(!organize.q||matchesPartQuery(p,primaryStock(p.id),locationName(primaryStock(p.id)?.locationId),organize.q))).map(p=>p.id);}
function organizeView(){const count=S.parts.filter(p=>missingFields(p).length).length,current=organizeCurrentIds(),allSelected=current.length>0&&current.every(id=>organize.selected.has(id));return `${header('BULK EDIT','批量整理','导入后连续补参数，也可以选中多条统一设置地点、库位和安全库存。',button('统一设置选中项','organize-uniform',true)+button('返回元件库','inventory-view'))}<div class="toolbar"><div class="search-box">${icon('search')}<input id="organizeSearch" value="${esc(organize.q)}" placeholder="搜索型号或电气参数"></div><label class="check-pill"><input id="pendingFilter" type="checkbox" ${organize.pending?'checked':''}>仅看待完善（${count}）</label><label class="check-pill"><input id="organizeSelectAll" type="checkbox" ${allSelected?'checked':''}><span id="organizeSelectLabel">全选当前结果（${current.length}）</span></label><button class="text-btn" data-act="organize-clear">清空选择</button></div><form id="organizeForm"><div class="panel table-panel"><div class="table-scroll"><table class="organize-table"><thead><tr><th><input class="organize-select-all" type="checkbox" aria-label="全选当前结果" ${allSelected?'checked':''}></th><th>元件 / 待完善</th><th>分类</th><th>封装</th><th>分类关键参数</th><th>制造商 / 立创</th><th>地点 / 库位</th><th>安全库存</th></tr></thead><tbody id="organizeBody">${organizeRows()}</tbody></table></div><div class="bulk-save"><span>当前表格中的修改会一次性校验并保存，避免只成功一部分。</span><button class="btn btn-primary" type="submit">保存本页修改</button></div></div></form>`;}
function organizeUniformForm(){if(!organize.selected.size){toast('请先选中要统一设置的元件');return;}openModal(`统一设置 ${organize.selected.size} 条元件`,`${'<p class="modal-intro">留空的项目保持原值。地点或库位有填写时，会用可追溯的调拨记录移动该元件当前主库位的全部数量。</p>'}<form id="bulkOrganizeForm"><div class="form-grid">${selectField('分类','category',[{value:'',label:'保持原分类'},...CATEGORIES.map(x=>({value:x,label:x}))],'')}${selectField('贴装方式','mount',[{value:'',label:'保持原方式'},...['贴片','插件'].map(x=>({value:x,label:x}))],'')}${field('封装','package','',{placeholder:'留空保持原值'})}${field('安全库存','minStock','',{type:'number',placeholder:'留空保持原值'})}${selectField('地点','locationId',[{value:'',label:'保持原地点'},...S.locations.map(l=>({value:l.id,label:l.name}))],'')}${field('库位','bin','',{placeholder:'留空保持原库位'})}</div>${actionsFooter('统一保存')}</form>`,{type:'bulk-organize'});}

function projectRowText(project){return (project?.rows||[]).map(r=>`${part(r.partId)?.sku||''},${r.perBoard},${r.reference||''}`).join('\n');}
function projectsView(){const projects=S.projects||[];if(!activeProjectId||!projects.some(p=>p.id===activeProjectId))activeProjectId=projects[0]?.id||'';const project=projects.find(p=>p.id===activeProjectId);if(!project)return `${header('PROJECT BOM','项目与备料','把常用BOM保存成项目，随时计算齐料、预留、拣料和缺料。',button('新建项目','project-new',true)+button('去导入 BOM','bom-view'))}${empty('还没有保存项目','可以新建项目粘贴“型号,每板用量,位号”，或先在 BOM 工具导入后保存。')}`;const analysis=projectAnalysis(project,S,projectBoards,projectRate),cost=projectCostEstimate(project,S,projectBoards,projectRate),previous=S.projects.find(x=>x.id===project.previousProjectId),diff=projectDiff(project,previous,S),reservedCount=(S.reservations||[]).filter(x=>x.projectId===project.id).reduce((n,x)=>n+x.qty,0);return `${header('PROJECT BOM','项目与备料','填写目标板数，直接查看最多可做、限制元件、拣料位置和缺料。',button('编辑项目','project-edit')+button('新建项目','project-new',true))}<div class="project-layout"><aside class="panel project-list">${projects.map(p=>`<button class="project-item ${p.id===project.id?'active':''}" data-project="${p.id}"><b>${esc(p.name)}</b><small>${esc(p.version||'未填版本')} · ${p.rows.length} 种</small></button>`).join('')}</aside><section class="project-main"><div class="panel project-controls"><div><b>${esc(project.name)} ${esc(project.version)}</b><small>${project.rows.length} 种元件 · 已预留 ${num(reservedCount)} 个</small></div><label>准备生产<input id="projectBoards" type="number" min="1" value="${projectBoards}"> 块</label><label>损耗率<input id="projectRate" type="number" min="0" max="100" step="0.1" value="${projectRate}"> %</label></div><div class="stats-grid project-stats"><div class="stat-card teal"><span>当前最多能配齐</span><strong>${num(analysis.maxBoards)}<small> 块</small></strong><div class="stat-foot">已扣除其他项目预留</div></div><div class="stat-card"><span>限制数量的元件</span><strong class="text-stat">${esc(analysis.bottlenecks.slice(0,2).map(x=>x.part?.sku).join('、')||'—')}</strong><div class="stat-foot">${analysis.bottlenecks.length} 种瓶颈元件</div></div><div class="stat-card"><span>做 ${projectBoards} 块还缺</span><strong>${analysis.shortages.length}<small> 种</small></strong><div class="stat-foot">合计 ${num(analysis.shortages.reduce((n,x)=>n+x.shortage,0))} 个</div></div><div class="stat-card"><span>预留状态</span><strong class="text-stat">${reservedCount?'已预留':'未预留'}</strong><div class="stat-foot">预留不扣实物，领料时才扣${reservedCount?` · 负责人：${esc(reservationOwners(project.id))}`:``}</div></div></div><div class="cost-strip"><b>项目成本估算</b><span>当前立创阶梯价：${cost.quote.map(x=>`${x.currency} ${x.total.toFixed(2)}`).join(' + ')||'无报价'}（${cost.unknownQuote.length} 种未报价）</span><span>历史实际采购价：${cost.actual.map(x=>`${x.currency} ${x.total.toFixed(2)}`).join(' + ')||'无记录'}（${cost.unknownActual.length} 种无记录）</span></div><div class="panel table-panel"><div class="panel-head"><div><h2>齐料与拣料单</h2><p>同一元件分散存放时列出所有可取库位。</p></div><div>${button('导出拣料单','project-pick')}${button('导出缺料单','project-shortage')}</div></div><div class="table-scroll"><table><thead><tr><th>元件</th><th>每板</th><th>需要</th><th>可用</th><th>缺少</th><th>去哪里取</th></tr></thead><tbody>${analysis.lines.map(x=>`<tr><td><button class="cell-button part-cell" data-act="detail" data-id="${x.partId}"><b>${esc(x.part?.sku)}</b><span>${esc(spec(x.part))}</span></button></td><td>${x.perBoard}</td><td>${x.required}</td><td>${x.available}<small class="cell-sub">实物 ${x.physical}${x.reservedOther?` · 他项预留 ${x.reservedOther}`:''}</small></td><td class="${x.shortage?'negative':'positive'}">${x.shortage||'齐料'}</td><td>${x.pickups.map(y=>`${esc(locationName(y.locationId))} / ${esc(y.bin||'未分配')}（${y.qty}）`).join('<br>')||'—'}</td></tr>`).join('')}</tbody></table></div><div class="project-actions">${button(reservedCount?'更新预留':'预留这些元件','project-reserve',true)}${reservedCount?button('取消预留','project-release'):''}${button('确认实际领料出库','project-issue',false,analysis.complete?'':'disabled')}${analysis.shortages.length?button('缺料加入采购清单','project-procure'):''}</div></div>${previous?`<div class="panel"><div class="panel-head"><div><h2>与上一版 BOM 的差异</h2><p>${esc(previous.name)} ${esc(previous.version)}</p></div></div><div class="diff-list">${diff.length?diff.map(x=>`<div><span class="tag neutral">${x.kind}</span><b>${esc(x.label)}</b><small>${esc(x.detail)}</small></div>`).join(''):'<p class="helper">元件种类和每板数量没有变化。</p>'}</div></div>`:''}<div class="panel"><div class="panel-head"><div><h2>板卡 / 成品库存</h2><p>已焊接整板在这里入库，不会拆回散料库存。</p></div><button class="text-btn" data-act="finished-new">＋ 登记整板</button></div><div class="finished-list">${(S.finishedGoods||[]).filter(x=>x.projectId===project.id).map(x=>`<div><b>${esc(x.name)}</b><span>${esc(locationName(x.locationId))} / ${esc(x.bin||'未分配')}</span><strong>${x.qty} 块</strong></div>`).join('')||'<p class="helper">暂时没有板卡库存。</p>'}</div></div></section></div>`;}

function procurementView(){const suggestions=procurementSuggestions(S),items=S.procurementItems||[];return `${header('PURCHASING','采购清单','把项目缺料、安全库存和已下单未到货放在同一处，减少重复采购。',button('手动添加采购项','purchase-new',true))}<div class="stats-strip"><div><span>待采购</span><b>${items.filter(x=>x.status==='needed').length} 项</b></div><div><span>已下单未到齐</span><b>${items.filter(x=>['ordered','partial'].includes(x.status)).length} 项</b></div><div><span>预计采购数量</span><b>${num(suggestions.reduce((n,x)=>n+x.suggested,0))}</b></div><div><span>已到齐</span><b>${items.filter(x=>x.status==='received').length} 项</b></div></div><div class="section-grid"><section class="panel"><div class="panel-head"><div><h2>建议补货</h2><p>建议数量已考虑未到货、最小起订量和包装倍数。</p></div></div><div class="purchase-needs">${suggestions.length?suggestions.map(x=>`<div><div><b>${esc(x.part.sku)}</b><small>可用 ${x.available} · 安全缺 ${x.safety}${x.projectShortage?` · 项目缺 ${x.projectShortage}`:''} · 在途 ${x.outstanding}</small></div><div><strong>建议 ${x.suggested}</strong>${x.quote?`<small>立创 ${x.quote.currency} ${x.quote.price}/个 · 档位 ${esc(x.quote.quantityTier)}</small>`:''}</div>${x.suggested?`<button class="text-btn" data-act="purchase-part" data-id="${x.part.id}" data-qty="${x.suggested}">加入 / 更新</button>`:''}</div>`).join(''):empty('当前没有补货建议','安全库存、项目缺料和在途数量都已平衡。')}</div></section><section class="panel"><div class="panel-head"><div><h2>采购进度</h2><p>收到货时可以分批入库，并记录实际采购价。</p></div></div><div class="purchase-orders">${items.slice().reverse().map(x=>{const p=part(x.partId),outstanding=Math.max(0,x.orderedQty-x.receivedQty);return `<div><div><b>${esc(p?.sku)}</b><small>${esc(x.supplier)} · ${x.status==='needed'?'待下单':x.status==='ordered'?'已下单':x.status==='partial'?'部分到货':x.status==='received'?'已到齐':'已取消'}${x.expectedAt?` · 预计 ${new Date(x.expectedAt).toLocaleDateString('zh-CN')}`:''}</small></div><div><strong>${x.receivedQty}/${x.orderedQty||x.requiredQty}</strong><small>${outstanding?`未到 ${outstanding}`:'无未到货'}</small></div><button class="text-btn" data-act="purchase-edit" data-id="${x.id}">编辑</button>${outstanding?`<button class="text-btn" data-act="purchase-receive" data-id="${x.id}">到货入库</button>`:''}</div>`;}).join('')||empty('采购清单为空','从项目缺料或安全库存建议加入。')}</div></section></div><p class="page-hint">项目成本中的商城价来自当前立创阶梯报价；到货时填写的价格保存为历史实际采购价，两者分开显示。</p>`;}

function storageView(){const boxes=S.containers||[];if(!activeContainerId||!boxes.some(x=>x.id===activeContainerId))activeContainerId=boxes[0]?.id||'';const box=boxes.find(x=>x.id===activeContainerId);return `${header('STORAGE MAP','元件盒与二维码','扫描盒子码看整盒，扫描元件码直接进入元件；移动库位后固定编号仍然有效。',button('新建元件盒','container-new',true)+button('扫描二维码','qr-scan'))}${boxes.length?`<div class="toolbar"><select id="containerSelect">${boxes.map(x=>`<option value="${x.id}" ${x.id===box.id?'selected':''}>${esc(x.name)} · ${esc(locationName(x.locationId))}</option>`).join('')}</select><div class="search-box">${icon('search')}<input id="storageSearch" value="${esc(storageQuery)}" placeholder="搜索盒内型号或参数"></div>${button('盒子二维码 / 标签','container-label')}${button('分配元件到格位','container-assign')}${button('按格连续盘点','container-stocktake')}</div><div class="panel box-panel"><div class="panel-head"><div><h2>${esc(box.name)}</h2><p>${box.rows} × ${box.cols} · ${esc(locationName(box.locationId))} · 点击有料格位查看元件</p></div></div><div class="bin-grid" style="--cols:${box.cols}">${Array.from({length:box.rows*box.cols},(_,i)=>{const cell=`${Math.floor(i/box.cols)+1}-${i%box.cols+1}`,stock=S.stocks.find(s=>s.containerId===box.id&&s.cell===cell),p=part(stock?.partId),hit=p&&(!storageQuery||matchesPartQuery(p,stock,locationName(box.locationId),storageQuery));return `<button class="bin-cell ${stock?'occupied':''} ${hit&&storageQuery?'highlight':''}" data-act="${stock?'detail':'container-assign-cell'}" data-id="${p?.id||''}" data-cell="${cell}"><span>${cell}</span><b>${esc(p?.sku||'空')}</b><small>${stock?`${stock.qty} 个`:'点击分配'}</small></button>`;}).join('')}</div></div>`:empty('还没有元件盒','新建一个 4×6 的24格元件盒，然后把库存分配到格位。',button('新建元件盒','container-new',true))}`;}

function draftsView(){const list=drafts();return `${header('OFFLINE DRAFTS','待同步草稿','离线记账不会改变确认库存；恢复连接后逐笔核对并提交。',button('快速领用','out',true))}<div class="snapshot-note"><b>${online?'电脑库存已连接':'正在显示离线快照'}</b><span>库存快照：${time(S.updatedAt||S.createdAt)} · ${list.length} 笔待提交</span></div><div class="panel draft-list">${list.length?list.map(d=>{const st=S.stocks.find(x=>x.id===d.stockId),p=part(st?.partId);return `<article><div><b>${esc(p?.sku||'库存项已变化')}</b><small>${time(d.createdAt)} · ${esc(locationName(st?.locationId))} / ${esc(st?.bin||'未分配')}</small><p>${d.kind} ${d.kind==='出库'?(d.qty*d.boards+d.loss):d.qty} 个 · ${esc(d.note||'无备注')}</p></div><div><span>记录时库存 ${d.snapshotQty}</span><span>当前快照 ${st?.qty??'—'}</span></div><button class="text-btn" data-act="draft-delete" data-id="${d.id}">删除</button><button class="btn btn-primary" data-act="draft-review" data-id="${d.id}" ${online?'':'disabled'}>核对提交</button></article>`;}).join(''):empty('没有待同步草稿','电脑离线时登记的快速领用、损耗和盘点会显示在这里。')}</div>`;}
function transactions(){const month=new Date().toISOString().slice(0,7);const active=S.orders.filter(o=>o.time.startsWith(month)&&!o.undoneBy&&o.type!=='撤销');const inc=active.filter(o=>o.type==='入库').flatMap(o=>o.lines).reduce((s,l)=>s+l.delta,0),out=active.filter(o=>o.type==='出库').flatMap(o=>o.lines).reduce((s,l)=>s-l.delta,0),loss=active.reduce((s,o)=>s+o.lines.reduce((x,l)=>x+(o.type==='损耗'?-l.delta:(l.loss||0)),0),0);return `${header('ACTIVITY LOG','出入库记录','每一笔用料，都是下一次备货的依据。',button(icon('download')+' 导出流水','export-events')+button(icon('plus')+' 记一笔','in',true))}<div class="stats-strip">${[['本月入库',`+${num(inc)}`],['本月出库',`−${num(out)}`],['本月损耗',num(loss)],['累计批次',num(S.orders.length)]].map(([t,n])=>`<div><span>${t}</span><b>${n}</b></div>`).join('')}</div><div class="toolbar"><div class="search-box">${icon('search')}<input id="txSearch" placeholder="搜索型号、项目、备注…" aria-label="搜索流水"></div></div><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>时间</th><th>类型</th><th>元件 / 批次</th><th>数量变化</th><th>备注</th><th>操作</th></tr></thead><tbody id="transactionBody">${transactionRows('')}</tbody></table></div></div>`;}
function transactionRows(q){const orders=S.orders.slice().reverse().filter(o=>[o.note,o.type,o.source,...o.lines.map(l=>part(S.stocks.find(s=>s.id===l.stockId)?.partId)?.sku)].join(' ').toLowerCase().includes(q.toLowerCase()));return orders.length?orders.map(o=>`<tr><td>${time(o.time)}</td><td><span class="tag ${o.type==='入库'?'good':o.type==='损耗'?'warning':'neutral'}">${o.type}</span>${o.undoneBy?'<small class="cell-sub">已撤销</small>':''}</td><td><button class="cell-button part-cell" data-act="order-detail" data-id="${o.id}"><b>${o.source==='BOM'?`BOM · ${o.boards} 块板`:esc(part(S.stocks.find(s=>s.id===o.lines[0]?.stockId)?.partId)?.sku||o.source)}</b><span>${o.lines.length} 行 · ${esc(o.source)}</span></button></td><td>${o.type==='调拨'?'库位间流转':num(o.lines.reduce((s,l)=>s+l.delta,0))}</td><td class="note-cell">${esc(o.note||'—')}</td><td><button class="text-btn" data-act="order-detail" data-id="${o.id}">详情 →</button></td></tr>`).join(''):`<tr><td colspan="6">${empty('没有匹配的记录','完成出入库后，这里会自动保存流水。')}</td></tr>`;}
function render(){if(!S)return;$('#navigation').innerHTML=[['dashboard','grid'],['inventory','box'],['projects','bom'],['procurement','bell'],['transactions','flow'],['bom','bom'],['alerts','bell'],['team','shield']].map(([v,ic])=>`<button class="nav-item ${view===v?'active':''}" data-view="${v}">${icon(ic)}${titles[v]}${v==='alerts'&&collectAlerts(S).length?`<em>${collectAlerts(S).length}</em>`:v==='drafts'&&drafts().length?`<em>${drafts().length}</em>`:''}</button>`).join('');$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));$$('.sidebar-foot [data-view]').forEach(el=>el.classList.toggle('active',view===el.dataset.view));$('#viewTitle').textContent=titles[view];$('#workspaceName').textContent=T.workspaces.find(w=>w.id===space)?.name||'选择元件库';$('#workspaceRole').textContent=roleName(currentRole);$('#demoSwitch').textContent='切换元件库 / 退出账号';$('#demoSwitch').dataset.act='team-switch';$('#demoBanner').hidden=true;$('#page').dataset.rev=S.rev;$('#page').innerHTML=({dashboard,inventory,organize:organizeView,transactions,bom:bomView,projects:projectsView,procurement:procurementView,storage:storageView,drafts:draftsView,alerts:alertsView,settings:teamSettingsView,team:teamView}[view])();if(view==='bom')renderBomRows();applyRoleUI();}
function setView(v){if(!titles[v])return;if(v==='team')teamLoad().then(()=>render()).catch(e=>toast(e.message,true));view=v;history.replaceState(null,'','#'+v);$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'});}
function bomDirectionPicker(){return `<div class="bom-direction"><button type="button" class="bom-kind-toggle ${bom.kind==='入库'?'selected':''}" data-bom-kind="入库"><b>＋ BOM 入库</b><small>按清单增加散料；缺少的型号自动建档。</small></button><button type="button" class="bom-kind-toggle ${bom.kind==='出库'?'selected':''}" data-bom-kind="出库"><b>− BOM 出库</b><small>按板数整单扣料；库存不足时整单不提交。</small></button></div>`;}
function bomView(){
  const step=bom.stage;
  return `${header('BOM ASSISTANT','BOM 工具','一份清单，完成散料入库、领料或保存项目。',button(icon('download')+' 下载模板','bom-template'))}
  <div class="stepper">${['导入清单','匹配元件','核对并提交'].map((t,i)=>`<div class="${step>=i?'current':''}"><span>${step>i?'✓':i+1}</span>${t}</div>`).join('')}</div>
  <div class="panel bom-workbench"><div class="panel-head"><div><h2>${step===0?'准备你的 BOM':step===1?'确认表格列含义':'核对用量与库位'}</h2><p>${step===0?'支持 Excel .xlsx、CSV、TSV；Excel 读取第一个工作表。':esc(bom.filename||'粘贴的 BOM')}</p></div>${step?button('重新导入','bom-reset'):''}</div>
  ${step===0?`${bomDirectionPicker()}<div class="bom-upload-area"><div class="notice-info">当前选择：<b>BOM ${bom.kind}</b>。请先确认方向，再选择文件。</div><label class="dropzone">${icon('bom')}<b>选择 BOM 文件进行${bom.kind}</b><span>型号、单板用量是常用必填项 · 最大 6MB</span><input id="bomFile" type="file" accept=".xlsx,.csv,.tsv,.txt" hidden></label><div class="separator">或者直接从表格复制粘贴</div><label class="field"><span>包含表头的 BOM 文本</span><textarea id="bomPaste" rows="7" placeholder="型号,每板用量,封装,参数,耐压,精度,介质,位号&#10;R-10K-0603,4,0603,10kΩ,,1%,,R1 R2 R3 R4&#10;C-100N-0603,6,0603,100nF,50V,10%,X7R,C1-C6"></textarea></label><label class="checkbox-field"><input id="bomAutoExclude" type="checkbox" ${bom.autoExclude?'checked':''}>自动排除螺丝、Test-Point、安装孔等非焊接项目（后续仍可单行强制纳入）</label><div class="modal-actions">${button(`继续 BOM ${bom.kind} →`,'bom-parse',true)}</div></div>`:
  step===1?`${bomDirectionPicker()}<div class="bom-upload-area"><div class="notice-info">正在准备 <b>BOM ${bom.kind}</b>。请核对列含义；100nF 与 0.1μF、4K7 与 4.7kΩ 会按电气值识别。</div><label class="checkbox-field"><input id="bomAutoExclude" type="checkbox" ${bom.autoExclude?'checked':''}>自动排除螺丝、Test-Point、安装孔等非焊接项目（确认列后显示结果，可单行强制纳入）</label><div class="form-grid">${[['sku','型号 / 唯一编号'],['qty','每板用量 *'],['value','参数 / 名称'],['package','封装'],['voltage','耐压'],['tolerance','精度'],['dielectric','介质'],['reference','位号'],['loss','手动损耗（额外个数）']].map(([key,label])=>selectField(label,'map-'+key,[{value:-1,label:'不使用此列'},...bom.table[0].map((v,i)=>({value:i,label:v||`第${i+1}列`}))],bom.mapping[key]??-1)).join('')}</div><div class="table-scroll sample-table"><table><thead><tr>${bom.table[0].map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${bom.table.slice(1,4).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="modal-actions">${button(`确认列并核对 BOM ${bom.kind} →`,'bom-map',true)}</div></div>`:
  `${bomDirectionPicker()}<div class="bom-options"><label>存放地点<select id="bomLocation">${S.locations.map(l=>`<option value="${l.id}" ${l.id===bom.locationId?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><label>板数<input id="bomBoards" type="number" min="1" step="1" value="${bom.boards}"></label><label>额外损耗率 %<input id="bomRate" type="number" min="0" max="100" step="0.1" value="${bom.lossRate}" ${bom.kind==='入库'?'disabled':''}></label>${bom.kind==='入库'?`<label>新库位名称<input id="bomBin" value="${esc(bom.bin||'')}" placeholder="新库位可选填"></label>`:''}<label class="bom-project">项目 / 备注<input id="bomNote" value="${esc(bom.note)}" placeholder="如：控制板 V2 · 20块"></label></div><div class="notice-info formula">${bom.kind==='出库'?'BOM 出库：总扣减 = 每板用量 × 板数 + 向上取整（用量 × 损耗率）+ 手动损耗。':'BOM 入库只增加可再次领用的散料。已焊接整板请到“项目与备料 → 板卡/成品库存”登记。'} 自动排除项保留在导出清单中，但不会阻止本次入库或出库。<span class="bom-exclude-actions">${button('强制纳入全部排除项','bom-include-all-excluded')}${button('恢复自动排除','bom-restore-excluded')}</span></div><div class="table-scroll"><table class="bom-table"><thead><tr><th>清单元件</th><th>库存匹配 / 库位</th><th>每板</th><th>手动损耗</th><th>合计</th><th>库存</th></tr></thead><tbody id="bomRows"></tbody></table></div><div class="bom-summary" id="bomSummary"></div>`}</div>`;
}
function renderBomRows(){
  if(bom.stage!==2||!$('#bomRows'))return;
  const plan=bomPlan(bom.rows,S,bom.kind,Number(bom.boards),Number(bom.lossRate)),selectable=S.stocks.filter(s=>s.locationId===bom.locationId);
  const activeByIndex=new Map(plan.lines.map(r=>[r.rowIndex,r]));
  $('#bomRows').innerHTML=bom.rows.map((raw,index)=>{
    if(raw.excluded&&!raw.forceInclude)return `<tr class="bom-ignored"><td><b>${esc(raw.sku||raw.value||'未命名')}</b><small class="cell-sub">${esc([raw.value,raw.package,raw.reference].filter(Boolean).join(' · '))}</small><small class="auto-draft">自动排除：${esc(raw.excludeReason||'非焊接项目')}</small></td><td colspan="4"><span class="tag warning">不进入元件仓，不参与本次${bom.kind}</span><button class="text-btn" data-act="bom-toggle-excluded" data-index="${index}">强制纳入</button></td><td>原始 BOM 保留</td></tr>`;
    const r=activeByIndex.get(index);if(!r)return '';
    const selected=r.stock&&!r.stock.draft?part(r.stock.partId):null,check=selected?compareBomPart(r,selected):null,candidates=matchDetails(r,S,bom.locationId),advice=check?[...check.conflicts,...check.unknowns,...check.differences]:candidates.length?[...new Set(candidates.flatMap(x=>[...x.conflicts,...x.unknowns,...x.differences]))]:[];
    return `<tr><td><b>${esc(r.sku||r.value||'未命名')}</b><small class="cell-sub">${esc([r.value,r.package,r.voltage,r.tolerance&&`±${r.tolerance}%`,r.dielectric,r.reference].filter(Boolean).join(' · '))}</small>${r.draft?`<small class="auto-draft">${r.stock?.draft||bom.rows[index].autoCreate?'将自动建档':'可按型号匹配'}</small>`:''}${r.forceInclude?'<small class="auto-draft">已强制纳入</small>':''}</td><td><select class="bom-match" data-row="${index}" aria-label="第${index+1}行匹配库位"><option value="">${bom.rows[index].autoCreate?`自动新建：${esc(bom.rows[index].draft?.name||'元件')}`:'请选择准确的元件和库位'}</option>${selectable.map(st=>`<option value="${st.id}" ${r.stockId===st.id?'selected':''}>${esc(stockName(st))}</option>`).join('')}${bom.kind==='入库'?S.parts.map(p=>`<option value="new:${p.id}" ${r.stockId==='new:'+p.id?'selected':''}>新库位：${esc(p.sku)} → ${esc(locationName(bom.locationId))} / ${esc(bom.bin||'未分配库位')}</option>`).join(''):''}</select>${advice.length?`<small class="match-advice ${check?.conflicts.length?'negative':''}">${esc(advice.slice(0,3).join('；'))}</small>`:''}${!r.stockId&&!bom.rows[index].autoCreate?`<button class="text-btn" data-act="bom-new-part" data-index="${index}">＋ 建立此元件</button>`:''}</td><td><input type="number" min="1" step="1" class="bom-qty" data-row="${index}" value="${Number.isFinite(r.perBoard)?r.perBoard:''}"></td><td><input type="number" min="0" step="1" class="bom-loss" data-row="${index}" value="${Number.isFinite(bom.rows[index].loss)?bom.rows[index].loss:''}" ${bom.kind==='入库'?'disabled':''}></td><td><b>${Number.isFinite(r.total)?num(r.total):'—'}</b><small class="cell-sub">含损耗 ${Number.isFinite(r.loss)?r.loss:'—'}</small></td><td>${r.stock?num(r.stock.qty):r.draft?'自动建档后计算':'待匹配'}</td></tr>`;
  }).join('');
  $('#bomSummary').innerHTML=`<div><b>${bom.rows.length} 行 · ${plan.ignored.length} 行已排除 · ${bom.boards} 块板 · 处理 ${Number.isFinite(plan.total)?num(plan.total):'—'} 个</b>${plan.errors.length?`<div class="bom-errors">${plan.errors.slice(0,6).map(x=>`<p>${esc(x)}</p>`).join('')}${plan.errors.length>6?`<p>另有 ${plan.errors.length-6} 项待处理</p>`:''}</div>`:`<p class="positive">${icon('check')} ${bom.kind==='入库'?'未建档元件会在提交时自动建立并入库。':'整单核对通过，提交前还会再次检查最新库存。'}${plan.ignored.length?' 排除项不会阻止本次操作。':''}</p>`}</div><div>${button(icon('download')+' 导出物料','bom-export')}${button('保存为项目','bom-save-project',false,plan.errors.length?'disabled':'')}<button class="btn btn-primary" data-act="bom-confirm" ${plan.errors.length||!plan.lines.length?'disabled':''}>确认整单${bom.kind} →</button></div>`;
}
function mapBom(){
  bom.rows.forEach(r=>{if(r.excluded&&!r.forceInclude){r.stockId='';r.autoCreate=false;return;}const details=matchDetails(r,S,bom.locationId),safe=details.filter(x=>x.safeAuto),existing=S.parts.find(p=>r.draft?.sku&&p.sku.toLowerCase()===r.draft.sku.toLowerCase())||S.parts.find(p=>r.sku&&p.sku.toLowerCase()===r.sku.trim().toLowerCase());r.autoCreate=false;if(safe.length===1)r.stockId=safe[0].stock.id;else if(details.length===0&&bom.kind==='入库'&&existing)r.stockId='new:'+existing.id;else if(details.length===0){r.stockId='';r.autoCreate=bom.kind==='入库';}else r.stockId='';});
}
function alertsView(){const alerts=collectAlerts(S),listed=S.parts,priceTracked=listed.filter(p=>p.watch&&p.lcscCode),s=S.settings;return `${header('WATCHLIST','关注与提醒','当前元件库中的所有元件都会列在关注清单中。',button('＋ 添加IC价格关注','watch-add',true)+button(icon('refresh')+' 刷新立创价格','lcsc-refresh'))}<div class="notice-banner ${s.lcscEnabled?'':'neutral-banner'}">${icon('bell')}<div><b>${s.lcscEnabled?'已开启立创商城价格提醒':'立创商城价格提醒已暂停'}</b><p>${s.lcscEnabled?`上次成功检查：${time(s.lcscLastSync)}。电脑服务运行时每6小时检查一次，也可手动刷新。`:'在设置中开启后，会读取指定IC的立创编号和各数量档价格。'}</p>${s.lcscLastSyncError?`<p class="negative">最近检查失败：${esc(s.lcscLastSyncError)}</p>`:''}</div><button class="text-btn" data-view="settings">提醒设置 →</button></div><div class="watch-grid"><section class="panel alerts-full"><div class="panel-head"><div><h2>待关注事项 <span class="count-badge">${alerts.length}</span></h2><p>包含安全库存、立创价格变化和有官方来源的生命周期消息。</p></div></div>${alerts.length?`<div class="rich-alert-list">${alerts.map(a=>`<article class="rich-alert"><span class="chip-icon ${a.level==='danger'?'red':'amber'}">${icon(a.kind==='stock'?'box':'bell')}</span><div><button class="cell-button" data-act="detail" data-id="${a.partId}"><b>${esc(a.title)}</b></button><p>${esc(a.body)}</p>${a.source?`<small>${esc(a.source)} · ${time(a.asOf)} ${a.stale?'<span class="tag warning">可能过期</span>':''}</small>`:''}${a.url?`<a class="source-link" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">查看原始来源 ↗</a>`:''}</div></article>`).join('')}</div>`:empty('当前没有待处理事项','元件库清单仍显示在右侧，需要时可单独开启立创价格关注。')}</section><section class="panel"><div class="panel-head"><div><h2>元件库关注清单</h2><p>${listed.length} 种元件 · ${priceTracked.length} 种已启用立创价格</p></div></div>${listed.length?listed.map(p=>`<button class="watch-item cell-button wide" data-act="detail" data-id="${p.id}"><div><b>${esc(p.sku)}</b><small>${p.category} · ${p.watch?(p.lcscCode?`已关注立创 ${esc(p.lcscCode)}`:'已开启价格关注，待填立创编号'):'库存清单'}</small></div>${icon('arrow')}</button>`).join(''):empty('元件库还没有内容','完成元件入库后会自动显示在这里，也可以添加只用于价格关注的IC。')}<div class="note-box">清单自动包含元件库全部内容。只有手动开启价格关注并填写立创编号的型号才会联网比较价格。</div></section></div>`;}
function settingsView(){return `${header('PREFERENCES','设置与备份','地点和数据，都由你自己掌握。')}<div class="settings-grid"><section class="panel settings-card"><div class="panel-head"><div><h2>存放地点</h2><p>库位可以细分为 A柜 / 02抽屉 / 元件盒。</p></div><button class="text-btn" data-act="location-new">＋ 添加地点</button></div><div class="location-manage">${S.locations.map(l=>`<div><span class="loc-dot teal"></span><b>${esc(l.name)}</b><small>${S.stocks.filter(s=>s.locationId===l.id).length} 个元件库位</small><button class="text-btn" data-act="location-edit" data-id="${l.id}">编辑</button></div>`).join('')}</div></section><section class="panel settings-card"><div class="panel-head"><div><h2>备份与恢复</h2><p>库存保存在这台电脑，所有设备连接后读取同一份数据。</p></div></div><div class="backup-actions">${button(icon('download')+' 导出完整备份','backup')}<label class="btn btn-secondary">导入备份<input id="restoreInput" type="file" accept=".json,application/json" hidden></label></div><p class="helper">每天首次修改前自动留一份备份。恢复前还会单独备份当前数据。建议定期把导出文件另存到其他设备。</p></section><section class="panel settings-card"><div class="panel-head"><div><h2>手机访问与同步</h2><p>${remoteAccess?'免费公网同步：手机可用任意 Wi-Fi 或移动数据。':isLocal?'本机连接：手机暂时需要与电脑在同一 Wi-Fi。':'正在通过远程连接访问电脑库存。'}</p></div></div><div class="settings-body"><p>${remoteAccess?'电脑在线并运行元件仓时，手机可从公网 HTTPS 链接访问；断线后自动重连并读取最新库存。':'在电脑上生成手机配对链接，手机打开后即可共用库存。'}</p>${isLocal?button(remoteAccess?'显示公网安装链接':'显示手机配对链接','connection',true):'<p class="helper">当前设备已经通过远程链接连接到电脑库存。</p>'}<div id="connectionLinks"></div><p class="helper">电脑关机、休眠或断网时，手机会立即显示最后一次同步的库存；离线领用、损耗和盘点可以保存为待同步草稿，恢复连接后人工核对再提交。重新打开应用、切回前台或网络恢复时会立即同步。</p><div class="apk-actions"><a class="btn btn-primary" href="/downloads/component-hub.apk" download>${icon('download')} 下载 Android APK v1.7</a><button class="text-btn" data-act="install">网页添加到桌面 →</button></div></div></section><section class="panel settings-card"><div class="panel-head"><div><h2>立创价格与芯片资料</h2><p>立创价格自动检查，芯片状态以制造商官方通知为准。</p></div></div><form id="settingsForm" class="settings-body"><div class="form-grid">${field('涨价提醒阈值 %','priceThreshold',S.settings.priceThreshold,{type:'number',min:.1,step:.1})}<label class="checkbox-field span-2"><input name="lcscEnabled" type="checkbox" ${S.settings.lcscEnabled?'checked':''}>开启立创商城价格提醒（每6小时检查）</label></div><div class="note-box">为元件填写立创商城编号（如 C17976）并开启关注，系统会读取立创各数量档的美元单价。价格上涨达到阈值时生成提醒；接口失败时保留旧价格，不生成错误提醒。</div><details class="details-section"><summary>高级：其他可信数据源 <span>用于厂商 PCN / EOL 等结构化消息</span></summary><div class="form-grid">${field('数据源 HTTPS 地址','feedUrl',S.settings.feedUrl,{full:true,placeholder:'https://你的数据服务/components.json'})}<label class="checkbox-field span-2"><input name="feedEnabled" type="checkbox" ${S.settings.feedEnabled?'checked':''}>开启其他数据源每日刷新</label></div><button type="button" class="text-btn" data-act="feed-help">查看接入格式</button></details><div class="note-box">芯片参数和生命周期应核对制造商官方产品页、数据手册和 PCN/EOL 通知；商城信息只用于采购与价格提醒。</div><div class="modal-actions"><button class="btn btn-primary" type="submit">保存设置</button></div></form></section></div>`;}
const commonDefaults={sku:'',name:'',category:'电容',mount:'贴片',package:'0603',minStock:0,watch:false,lcscCode:'',tolerance:'',value:'',description:''};
function partForm(id='',prefill={}){const p=id?{...part(id)}:{...commonDefaults,...prefill};const fromBom=prefill.fromBom;const details=[['制造商','manufacturer'],['立创商城编号（如 C17976）','lcscCode'],['额定电压 / 耐压','voltage'],['额定电流','current'],['额定功率','power'],['介质 / 材料','dielectric'],['工作温度','temperature'],['温度系数 ppm/℃','tcr'],['器件类型','type'],['频率 / 频率范围','frequency'],['RDS(on) / 内阻','rdson'],['栅极电压 / 驱动条件','vgs'],['极性 / 沟道类型','polarity'],['功能','function'],['引脚数量','pins'],['接口 / 协议','interface']];
openModal(id?'编辑元件参数':prefill.ocr?'核对识别信息并入库':'新增元件',`<p class="modal-intro">${prefill.ocr?'识别仅作为填写建议。请对照原标签逐项核对型号、封装、数量和地点。':'型号相同但规格不同的元件，请使用独立编号，例如 R-10K-0603-1%。'}</p><form id="partForm"><div class="form-grid">${field('唯一编号 / 型号','sku',p.sku,{required:true,placeholder:'如：R-10K-0603-1%'})}${field('名称','name',p.name,{required:true,placeholder:'如：10kΩ 电阻'})}${selectField('分类','category',CATEGORIES,p.category)}${selectField('贴装方式','mount',['贴片','插件'],p.mount)}${field('封装','package',p.package,{list:'packages',placeholder:'可选，也可直接输入'})}${field('标称值','value',p.value,{list:'values',placeholder:'如：10kΩ / 100nF / 47μH'})}${field('精度 %','tolerance',p.tolerance,{list:'tolerances',placeholder:'选择常用精度，或输入其他值'})}${field('安全库存（所有地点合计）','minStock',p.minStock,{type:'number'})}</div>${datalist('packages',['0201','0402','0603','0805','1206','1210','1812','2512','SOT-23','SOT-23-5','SOT-223','SMA','SMB','SOIC-8','QFN-32','LQFP-48','DIP-8','轴向','径向'])}${datalist('values',['10Ω','100Ω','1kΩ','4.7kΩ','10kΩ','100kΩ','1MΩ','10pF','100pF','1nF','10nF','100nF','1μF','10μF','100μF','1μH','10μH','47μH'])}${datalist('tolerances',['0.1','0.5','1','2','5','10','20'])}<div class="preset-line"><span>常用精度</span>${['1','5','10','20'].map(x=>`<button type="button" class="preset-chip" data-act="tolerance" data-value="${x}">±${x}%</button>`).join('')}</div><details class="details-section"><summary>详细电气参数 <span>按需要选填</span></summary><div class="form-grid">${details.map(([label,key])=>field(label,key,p[key]||'',{list:{voltage:'voltages',power:'powers',dielectric:'dielectrics',polarity:'polarities'}[key]})).join('')}</div>${datalist('voltages',['6.3V','10V','16V','25V','50V','100V','400V'])}${datalist('powers',['0.0625W','0.1W','0.125W','0.25W','0.5W','1W','2W','5W'])}${datalist('dielectrics',['C0G/NP0','X7R','X5R','Y5V','铝电解','钽','薄膜','厚膜','金属膜'])}${datalist('polarities',['无极性','有极性','NPN','PNP','N沟道','P沟道'])}</details><details class="details-section"><summary>资料与采购链接</summary><div class="form-grid">${field('芯片厂商官方数据手册 / 产品页','datasheetUrl',p.datasheetUrl,{full:true,type:'url',placeholder:'https://厂商官网/...'})}${field('采购链接（留空则搜索立创商城）','purchaseUrl',p.purchaseUrl,{full:true,type:'url',placeholder:'https://www.szlcsc.com/...'})}</div></details><label class="checkbox-field"><input type="checkbox" name="watch" ${p.watch?'checked':''}>关注立创商城价格与生命周期</label><div class="field"><label for="f-description">备注 / 补充参数</label><textarea id="f-description" name="description" rows="3">${esc(p.description||'')}</textarea></div>${!id?`<div class="form-divider">初始库存</div><div class="form-grid">${selectField('地点','locationId',S.locations.map(l=>({value:l.id,label:l.name})),prefill.locationId||loc||S.locations[0].id)}${field('库位','bin',prefill.bin||'',{placeholder:'如：A柜 · 02-03'})}${field('初始数量','qty',prefill.qty??0,{type:'number',required:true})}</div>`:''}${actionsFooter(id?'保存参数':Number(prefill.qty)>0?'确认参数并入库':'保存元件')}</form>`,{type:'part',partId:id,fromBom,existing:p});}
function stockForm(kind,stockId='',prefill={}){if(!S.parts.length){partForm();return;}const selected=S.stocks.find(s=>s.id===stockId)||S.stocks.find(s=>!loc||s.locationId===loc)||S.stocks[0];const isIn=kind==='入库';openModal(`登记${kind}`,`<p class="modal-intro">${kind==='入库'?'选择已有元件，并确认实际入库地点与库位。':kind==='出库'?'用量 × 板数，额外损耗以“个”填写。':'损耗或盘点都会保留完整记录。'}</p><form id="stockForm"><div class="form-grid">${isIn?selectField('元件','partId',S.parts.map(p=>({value:p.id,label:`${p.sku} · ${p.name}`})),prefill.partId||selected?.partId,true):selectField('来源元件与库位','stockId',S.stocks.map(st=>({value:st.id,label:stockName(st)})),selected?.id,true)}${isIn?selectField('入库地点','locationId',S.locations.map(l=>({value:l.id,label:l.name})),prefill.locationId||selected?.locationId)+field('入库库位','bin',prefill.bin??selected?.bin??'',{placeholder:'如：A柜 · 02-03'}):''}${field(kind==='出库'?'每板用量 / 单次用量':kind==='盘点'?'实盘数量':'数量','qty',prefill.qty??(kind==='盘点'?selected?.qty:1),{type:'number',min:kind==='盘点'?0:1,required:true})}${kind==='出库'?field('板数（单次领用填1）','boards',1,{type:'number',min:1,required:true})+field('额外损耗（个）','loss',0,{type:'number'}):''}${field('项目 / 单号 / 原因','note',prefill.note||'',{full:true,required:kind==='损耗'||kind==='盘点',placeholder:kind==='损耗'?'如：焊接损坏 3 颗':'方便以后追溯'})}</div><div class="notice-info" id="stockCalculation"></div>${actionsFooter(`确认${kind}`)}</form>`,{type:'stock',kind});updateStockCalculation();}
function bulkStockOutForm(){const stocks=[...inventorySelected].map(id=>S.stocks.find(s=>s.id===id)).filter(s=>s&&s.qty>0);if(!stocks.length)throw new Error('请选择至少一个有库存的库位');const totalQty=stocks.reduce((n,s)=>n+s.qty,0);const preview=stocks.slice(0,10).map(s=>`${stockName(s)}：${num(s.qty)} 个`).join('；');openModal('批量出库已选库存',`<p class="modal-intro">将把选中的 ${stocks.length} 个库位全部扣减到 0，共 ${num(totalQty)} 个。系统会整批校验，任何一个库位数量异常都不会提交。</p><div class="note-box">${esc(preview)}${stocks.length>10?`；另有 ${stocks.length-10} 个库位`:''}</div><form id="bulkStockOutForm"><div class="form-grid">${field('项目 / 单号 / 原因','note','',{full:true,required:true,placeholder:'如：主控板 V1.4 全部用完'})}</div>${actionsFooter('确认批量出库')}</form>`,{type:'bulk-stock-out',stocks});}
function updateStockCalculation(){const f=$('#stockForm');if(!f)return;const d=Object.fromEntries(new FormData(f));const {kind}=modalContext;const qty=Number(d.qty),boards=Number(d.boards||1),loss=Number(d.loss||0);const st=kind==='入库'?S.stocks.find(s=>s.partId===d.partId&&s.locationId===d.locationId&&s.bin===d.bin):S.stocks.find(s=>s.id===d.stockId);const current=st?.qty||0;const delta=kind==='出库'?-(qty*boards+loss):kind==='损耗'?-qty:kind==='盘点'?qty-current:qty;$('#stockCalculation').textContent=`当前 ${current} 个 → 操作后 ${current+delta} 个${kind==='出库'?`（用料 ${qty*boards} + 损耗 ${loss}）`:''}${current+delta<0?' · 库存不足，无法提交':''}`;}
function transferForm(stockId=''){if(!S.stocks.length){toast('请先建立元件库存');return;}const selected=S.stocks.find(s=>s.id===stockId)||S.stocks[0];openModal('地点与库位调拨',`<p class="modal-intro">调拨保持元件总数量不变，两端库存会同时更新。</p><form id="transferForm"><div class="form-grid">${selectField('来源元件与库位','stockId',S.stocks.map(st=>({value:st.id,label:stockName(st)})),selected.id,true)}${selectField('目标地点','locationId',S.locations.map(l=>({value:l.id,label:l.name})),S.locations.find(l=>l.id!==selected.locationId)?.id||selected.locationId)}${field('目标库位','bin','',{placeholder:'如：实验台 · 元件盒 3'})}${field('调拨数量','qty',1,{type:'number',min:1,required:true})}${field('备注','note','',{full:true})}</div>${actionsFooter('确认调拨')}</form>`,{type:'transfer'});}
function detail(partId){
  const p=part(partId);if(!p)return;const stocks=S.stocks.filter(s=>s.partId===partId),records=S.observations.filter(o=>o.partId===partId).slice().sort((a,b)=>b.asOf.localeCompare(a.asOf)),usage=(S.usageRecords||[]).filter(x=>x.partId===partId).slice().reverse(),subs=(S.substitutions||[]).filter(x=>x.partId===partId);const labelMap={manufacturer:'制造商',value:'标称值',tolerance:'精度 %',voltage:'耐压 / 电压',power:'功率',current:'额定电流',dielectric:'介质 / 材料',temperature:'工作温度',tcr:'温度系数',type:'器件类型',frequency:'频率',rdson:'RDS(on) / 内阻',vgs:'栅极电压 / 测试条件',polarity:'极性 / 沟道',function:'功能',pins:'引脚数',interface:'接口'};
  openModal(p.name,`<div class="detail-top"><span class="category-badge cat-${CATEGORIES.indexOf(p.category)}">${p.category}</span><span>${p.mount} · ${esc(p.package||'未填封装')}</span><span class="tag ${p.watch?'good':'neutral'}">${p.watch?'已关注':'未关注'}</span>${missingFields(p).length?`<span class="tag warning">待完善 ${missingFields(p).length} 项</span>`:''}</div><p class="detail-sku">${esc(p.sku)}</p><div class="detail-stock"><div><span>实物总库存</span><strong>${num(total(p.id))}<small> 个</small></strong></div><div><span>项目预留 / 其他可用</span><b>${num(reserved(p.id))} / ${num(Math.max(0,total(p.id)-reserved(p.id)))}</b></div>${button('编辑参数','edit-part',false,`data-id="${p.id}"`)}${button('二维码标签','part-label',false,`data-id="${p.id}"`)}</div><div class="detail-links"><a class="btn btn-secondary" href="${esc(p.purchaseUrl||lcscSearchUrl(p.lcscCode||p.sku))}" target="_blank" rel="noopener noreferrer">${icon('link')}${p.purchaseUrl?'打开采购链接':'立创商城采购'}</a><a class="btn btn-secondary" href="${esc(officialPartLink(p)?.url||lcscSearchUrl(p.sku))}" target="_blank" rel="noopener noreferrer">${icon('bom')}${officialPartLink(p)?.label||'立创型号资料（未识别厂商）'}</a></div><div class="form-divider">它们放在哪里</div>${stocks.map(st=>`<div class="stock-location"><div>${icon('pin')}<b>${esc(locationName(st.locationId))}</b><small>${esc(st.bin||'未分配库位')}</small></div><strong>${num(st.qty)} 个</strong><div class="row-actions"><button class="text-btn" data-act="stock-in" data-id="${st.id}">入库</button><button class="text-btn" data-act="stock-out" data-id="${st.id}">出库</button><button class="text-btn" data-act="stock-loss" data-id="${st.id}">损耗</button><button class="text-btn" data-act="stock-transfer" data-id="${st.id}">调拨</button><button class="text-btn" data-act="stock-count" data-id="${st.id}">盘点</button></div></div>`).join('')||'<p class="subtle">仅价格关注，尚无实体库存。</p>'}<div class="form-divider">元件参数</div><dl class="parameter-grid">${Object.entries(labelMap).filter(([key])=>p[key]).map(([key,label])=>`<div><dt>${label}</dt><dd>${esc(p[key])}</dd></div>`).join('')||'<p class="subtle">尚未补充电气参数，可通过“编辑参数”填写。</p>'}</dl>${p.description?`<div class="note-box preserve">${esc(p.description)}</div>`:''}<div class="form-divider"><span>实测使用记录</span><button class="text-btn" data-act="usage-new" data-id="${p.id}">＋ 新增记录</button></div><div class="experience-list">${usage.length?usage.map(x=>`<article><b>${esc(S.projects.find(y=>y.id===x.projectId)?.name||'未关联项目')}</b><p>${esc(x.condition||'未填条件')}</p><small>${esc(x.result||'未填结果')}${x.issue?` · 问题：${esc(x.issue)}`:''}</small></article>`).join(''):'<p class="subtle">还没有实测记录。</p>'}</div><div class="form-divider"><span>替代料关系</span><button class="text-btn" data-act="substitution-new" data-id="${p.id}">＋ 添加替代料</button></div><div class="experience-list">${subs.length?subs.map(x=>{const alt=part(x.substitutePartId);return `<article><b>${esc(alt?.sku||'元件已删除')} · ${x.status==='verified'?'已验证':'候选'}</b><p>${esc(x.conditions||'尚未写明验证条件')}</p><small>${esc(S.projects.find(y=>y.id===x.projectId)?.name||'通用 / 未关联项目')} ${esc(x.note||'')}</small></article>`;}).join(''):'<p class="subtle">还没有替代料。IC 和 MOS 管不会按封装或少量额定值自动认定可替代。</p>'}</div><div class="form-divider"><span>价格记录</span><button class="text-btn" data-act="price-new" data-id="${p.id}">＋ 记录单价</button></div>${records.length?`<div class="price-history">${records.slice(0,8).map(o=>`<div><b>${o.price!=null?`${esc(o.currency)} ${o.price} / 个`:esc(({active:'在产',nrnd:'不推荐新设计',eol:'EOL通知',obsolete:'已停产'})[o.lifecycle]||'状态记录')}</b><small>${esc(o.source)} · 数量档 ${esc(o.quantityTier||'1')} · ${time(o.asOf)} ${o.kind==='manual'?'· 手动记录':o.kind==='purchase'?'· 实际采购':''}</small>${o.sourceUrl?`<a href="${esc(o.sourceUrl)}" target="_blank" rel="noopener noreferrer">来源 ↗</a>`:''}</div>`).join('')}</div>`:'<p class="subtle">还没有价格记录。</p>'}`,{type:'detail',partId});
}
function orderDetail(orderId){const o=S.orders.find(o=>o.id===orderId);if(!o)return;openModal(`${o.source} · ${o.type}`,`<p class="modal-intro">${time(o.time)} · 批次 ${o.id.slice(0,8)}${o.undoneBy?' · 已撤销':''}</p><div class="note-box">${esc(o.note||'没有填写备注')}${o.source==='BOM'?` · ${o.boards} 块板`:''}</div><div class="table-scroll"><table><thead><tr><th>元件 / 位置</th><th>用量</th><th>损耗</th><th>库存变化</th></tr></thead><tbody>${o.lines.map(l=>{const st=S.stocks.find(s=>s.id===l.stockId);return `<tr><td><b>${esc(part(st?.partId)?.sku||'—')}</b><small class="cell-sub">${esc(locationName(st?.locationId))} · ${esc(st?.bin||'未分配库位')}</small></td><td>${num(l.base??Math.abs(l.delta))}</td><td>${num(l.loss||0)}</td><td class="${l.delta>0?'positive':'negative'}">${l.delta>0?'+':''}${num(l.delta)}</td></tr>`;}).join('')}</tbody></table></div><p class="helper">撤销会产生一条反向流水。涉及库位若已有后续操作，需先撤销后续操作，或通过盘点修正。</p><div class="modal-actions">${button('关闭','close-modal')}${!o.undoneBy&&o.type!=='撤销'?button('撤销此批次','undo-confirm',false,`data-id="${o.id}"`):''}</div>`,{type:'order',orderId});}
function priceForm(partId){const p=part(partId);openModal('记录采购单价',`<p class="modal-intro">${esc(p.sku)} · 默认按立创商城记录；同一来源、币种和数量档的连续记录才会比较。</p><form id="priceForm"><div class="form-grid">${field('单价 / 个','price','',{type:'number',min:.0000001,step:'any',required:true})}${selectField('币种','currency',['CNY','USD','EUR','JPY','HKD'],'CNY')}${field('供应商 / 价格来源','source','立创商城',{required:true})}${field('数量档','quantityTier','1',{required:true,placeholder:'如：1 / 100 / 整盘'})}${field('来源链接（可选）','sourceUrl',p.purchaseUrl||lcscSearchUrl(p.sku),{type:'url',full:true,placeholder:'https://...'})}</div>${actionsFooter('保存价格记录')}</form>`,{type:'price',partId});}
function priceWatchForm(){openModal('添加IC价格关注',`<p class="modal-intro">可以填写元件库里已有的IC型号，也可以新增一个仅用于价格关注的IC。立创编号用于准确匹配具体商品。</p><form id="watchPartForm"><div class="form-grid">${field('IC型号 / 唯一编号','sku','',{required:true,placeholder:'如：STM32G431CBT6'})}${field('立创商城编号','lcscCode','',{required:true,placeholder:'如：C529313'})}${field('名称（可选）','name','',{placeholder:'留空则使用IC型号'})}${field('制造商','manufacturer','',{placeholder:'如：ST / TI / NXP'})}${selectField('贴装方式','mount',['贴片','插件'],'贴片')}${field('封装','package','',{placeholder:'如：LQFP-48 / QFN-32'})}${field('芯片厂商官方产品页','datasheetUrl','',{type:'url',full:true,placeholder:'https://厂商官网/...'})}</div>${actionsFooter('添加价格关注')}</form>`,{type:'watch-part'});}
function projectForm(id='',prefill={}){const p=id?S.projects.find(x=>x.id===id):null,source=p||prefill,rows=p?projectRowText(p):(prefill.rows||'');openModal(id?'编辑项目 BOM':'保存项目 BOM',`<p class="modal-intro">每行填写“型号,每板用量,位号”。型号必须已在元件库建档；编辑已预留项目时，保存会释放原预留，避免旧BOM继续占用。</p><form id="projectForm"><div class="form-grid">${field('项目名称','name',source.name||'',{required:true,placeholder:'如：控制板'})}${field('版本','version',source.version||'',{placeholder:'如：V1.2'})}${selectField('上一版 BOM','previousProjectId',[{value:'',label:'不比较上一版'},...S.projects.filter(x=>x.id!==id).map(x=>({value:x.id,label:`${x.name} ${x.version}`}))],source.previousProjectId||'',true)}<div class="field span-2"><label>项目 BOM（型号,每板用量,位号）</label><textarea name="rows" rows="10" required placeholder="R-10K-0603,4,R1 R2 R3 R4&#10;C-100N-0603,6,C1-C6">${esc(rows)}</textarea></div>${field('项目备注','note',source.note||'',{full:true})}</div>${actionsFooter('保存项目')}</form>`,{type:'project',projectId:id});}
function projectFromBom(){const rows=bom.rows.filter(r=>!(r.excluded&&!r.forceInclude)).map(r=>{const st=S.stocks.find(x=>x.id===r.stockId),partId=st?.partId||(r.stockId?.startsWith('new:')?r.stockId.slice(4):''),p=part(partId);return p?`${p.sku},${r.perBoard},${r.reference||''}`:'';});if(rows.some(x=>!x))throw new Error('BOM中还有自动建档元件，请先完成散料入库，再保存为项目');if(!rows.length)throw new Error('当前 BOM 全部是自动排除项，无法保存为项目');projectForm('',{name:bom.note||bom.filename.replace(/\.[^.]+$/,''),rows:rows.join('\n')});}
function purchaseForm(partId='',itemId='',qty=0){const item=(S.procurementItems||[]).find(x=>x.id===itemId),p=item?part(item.partId):part(partId);openModal(item?'编辑采购项':'加入采购清单',`<p class="modal-intro">需求、在途和到货分开记录；建议购买数量会按最小起订量和包装倍数取整。</p><form id="purchaseForm"><div class="form-grid">${selectField('元件','partId',S.parts.map(x=>({value:x.id,label:`${x.sku} · ${x.name}`})),item?.partId||p?.id||S.parts[0]?.id,true)}${selectField('需求来源','needType',[{value:'manual',label:'手动补货'},{value:'safety',label:'安全库存'},{value:'project',label:'项目缺料'}],item?.needType||'manual')}${field('需求数量','requiredQty',item?.requiredQty??qty,{type:'number',required:true})}${field('已下单数量','orderedQty',item?.orderedQty??0,{type:'number'})}${field('最小起订量 MOQ','moq',item?.moq??1,{type:'number',min:1})}${field('包装倍数','packMultiple',item?.packMultiple??1,{type:'number',min:1})}${field('供应商','supplier',item?.supplier||'立创商城')}${field('预计到货时间','expectedAt',item?.expectedAt||'',{type:'date'})}${field('历史实际采购单价','actualUnitPrice',item?.actualUnitPrice??'',{type:'number',step:'any'})}${selectField('币种','currency',['CNY','USD','EUR','JPY','HKD'],item?.currency||'CNY')}${field('备注','note',item?.note||'',{full:true})}</div>${actionsFooter(item?'保存采购进度':'加入采购清单')}</form>`,{type:'purchase',itemId});}
function receiveForm(itemId){const item=S.procurementItems.find(x=>x.id===itemId),p=part(item.partId),left=item.orderedQty-item.receivedQty;openModal('采购到货入库',`<p class="modal-intro">${esc(p.sku)} · 已到 ${item.receivedQty} / ${item.orderedQty}，本次最多 ${left}。支持部分到货和分批入库。</p><form id="receiveForm"><div class="form-grid">${field('本次到货数量','qty',left,{type:'number',min:1,required:true})}${selectField('入库地点','locationId',S.locations.map(l=>({value:l.id,label:l.name})),S.locations[0].id)}${field('库位','bin',primaryStock(p.id)?.bin||'',{placeholder:'如：A柜 · 02-03'})}${field('本批实际单价','actualUnitPrice',item.actualUnitPrice??'',{type:'number',step:'any'})}${field('到货备注','note','',{full:true,placeholder:'如：订单号、批次、部分到货'})}</div>${actionsFooter('确认到货并入库')}</form>`,{type:'receive',itemId});}
function usageForm(partId){openModal('新增实测使用记录',`<p class="modal-intro">记录在哪块板、什么条件下验证，以及发现过的问题。它不会自动推断可替代关系。</p><form id="usageForm"><div class="form-grid">${selectField('适用项目','projectId',[{value:'',label:'未关联项目'},...S.projects.map(x=>({value:x.id,label:`${x.name} ${x.version}`}))],'',true)}${field('测试 / 使用条件','condition','',{full:true,placeholder:'如：VGS=3.3V、负载2A、室温25℃'})}${field('实测结果','result','',{full:true,placeholder:'如：连续运行30分钟，壳温62℃'})}${field('问题与限制','issue','',{full:true,placeholder:'如：低温启动偶发失败'})}</div>${actionsFooter('保存实测记录')}</form>`,{type:'usage',partId});}
function substitutionForm(partId){openModal('建立替代料关系',`<p class="modal-intro">候选仅表示值得评估；“已验证”必须填写具体项目或电气、热、机械条件。</p><form id="substitutionForm"><div class="form-grid">${selectField('替代型号','substitutePartId',S.parts.filter(x=>x.id!==partId).map(x=>({value:x.id,label:`${x.sku} · ${x.name}`})),'',true)}${selectField('验证状态','status',[{value:'candidate',label:'候选，尚未验证'},{value:'verified',label:'已验证'}],'candidate')}${selectField('适用项目','projectId',[{value:'',label:'通用 / 未关联'},...S.projects.map(x=>({value:x.id,label:`${x.name} ${x.version}`}))],'',true)}${field('适用与验证条件','conditions','',{full:true,placeholder:'IC/MOS请写明电压、电流、驱动、温升、引脚和软件兼容等'})}${field('备注','note','',{full:true})}</div>${actionsFooter('保存替代关系')}</form>`,{type:'substitution',partId});}
function containerForm(id=''){const box=S.containers.find(x=>x.id===id);openModal(id?'编辑元件盒':'新建元件盒',`<form id="containerForm"><div class="form-grid">${field('元件盒名称','name',box?.name||'',{required:true,placeholder:'如：A柜 24格盒-01'})}${selectField('所在地点','locationId',S.locations.map(l=>({value:l.id,label:l.name})),box?.locationId||S.locations[0].id)}${field('行数','rows',box?.rows||4,{type:'number',min:1,required:true})}${field('列数','cols',box?.cols||6,{type:'number',min:1,required:true})}${field('备注','note',box?.note||'',{full:true})}</div>${actionsFooter('保存元件盒')}</form>`,{type:'container',containerId:id});}
function assignContainer(cell=''){const box=S.containers.find(x=>x.id===activeContainerId);if(!box)return;openModal('分配元件到格位',`<p class="modal-intro">会把所选库位的全部数量调拨到 ${esc(box.name)}；固定元件二维码仍然有效。</p><form id="containerAssignForm"><div class="form-grid">${selectField('元件与当前库位','stockId',S.stocks.filter(x=>x.qty>0).map(x=>({value:x.id,label:stockName(x)})),'',true)}${selectField('目标格位','cell',Array.from({length:box.rows*box.cols},(_,i)=>{const c=`${Math.floor(i/box.cols)+1}-${i%box.cols+1}`;return {value:c,label:`${c}${S.stocks.some(s=>s.containerId===box.id&&s.cell===c)?'（已有元件）':''}`}}),cell||'1-1')}</div>${actionsFooter('确认放入格位')}</form>`,{type:'container-assign',containerId:box.id});}
function containerStocktakeForm(){const box=S.containers.find(x=>x.id===activeContainerId),stocks=S.stocks.filter(x=>x.containerId===box.id).sort((a,b)=>a.cell.localeCompare(b.cell,undefined,{numeric:true}));if(!stocks.length){toast('这个元件盒还没有已分配的元件');return;}openModal(`${box.name} · 连续盘点`,`<p class="modal-intro">按格填写实盘数量，全部完成后统一查看并提交差异；未修改的格位不会产生流水。</p><form id="containerStocktakeForm"><div class="stocktake-grid">${stocks.map(st=>`<label><span>${esc(st.cell)} · ${esc(part(st.partId)?.sku)}</span><small>确认库存 ${st.qty}</small><input name="count-${st.id}" type="number" min="0" step="1" value="${st.qty}"></label>`).join('')}</div>${field('盘点备注','note',box.name,{full:true})}${actionsFooter('统一提交盘点差异')}</form>`,{type:'container-stocktake',containerId:box.id,stocks:stocks.map(x=>x.id)});}
function finishedForm(projectId){const project=S.projects.find(x=>x.id===projectId);openModal('登记板卡 / 成品库存',`<p class="modal-intro">已焊接整板在这里独立记账，不会增加板上散料库存。</p><form id="finishedForm"><div class="form-grid">${field('板卡 / 成品名称','name',`${project.name} ${project.version}`.trim(),{required:true})}${selectField('操作','kind',['入库','出库','盘点'],'入库')}${selectField('地点','locationId',S.locations.map(l=>({value:l.id,label:l.name})),S.locations[0].id)}${field('库位','bin','',{placeholder:'如：成品柜 · 2层'})}${field('数量（块）','qty',1,{type:'number',required:true})}${field('备注','note','',{full:true})}</div>${actionsFooter('保存板卡库存')}</form>`,{type:'finished',projectId});}
function qrLabel(kind,id,title,subtitle=''){const code=`CHUB:${kind==='part'?'P':'B'}:${id}`,svg=window.ComponentQR?.svg(code,7)||'';openModal(`${title} · 二维码标签`,`<div class="qr-label">${svg}<div><b>${esc(title)}</b><p>${esc(subtitle)}</p><code>${esc(code)}</code></div></div><p class="helper">二维码绑定固定编号。元件移动库位或修改数量后仍然可以继续使用。</p><div class="modal-actions">${button('关闭','close-modal')}${button('下载 SVG 标签','label-download',true)}</div>`,{type:'label',svg,name:`${title}-二维码.svg`});}
function scanHub(){openModal('扫一扫 / 拍标签',`<div class="scan-hub"><label class="dropzone photo-drop">${icon('camera')}<b>扫描元件盒或元件二维码</b><span>拍照或从相册选择二维码图片</span><input id="qrScanFile" type="file" accept="image/*" capture="environment" hidden></label>${button('拍标签识别入库','scan')}<div class="field"><label>二维码文字（也可手动输入）</label><input id="qrManual" placeholder="CHUB:P:固定编号"></div><button class="btn btn-secondary" data-act="qr-open-manual">打开</button><div id="qrScanResult"></div></div>`);}
async function decodeQrFile(file){if(!('BarcodeDetector' in window))throw new Error('当前手机系统不支持图片解码，请使用系统相机扫二维码，或手动输入二维码下方文字');const img=await createImageBitmap(file),detector=new BarcodeDetector({formats:['qr_code']}),codes=await detector.detect(img);img.close?.();if(!codes.length)throw new Error('没有识别到二维码，请靠近后重拍');openQrCode(codes[0].rawValue);}
function openQrCode(code){const m=String(code||'').trim().match(/^CHUB:([PB]):([0-9a-f-]{36})$/i);if(!m)throw new Error('这不是元件仓二维码');closeModal();if(m[1].toUpperCase()==='P'){if(!part(m[2]))throw new Error('元件不存在或尚未同步');detail(m[2]);}else{if(!S.containers.some(x=>x.id===m[2]))throw new Error('元件盒不存在或尚未同步');activeContainerId=m[2];setView('storage');}}
function locationForm(id=''){const l=S.locations.find(x=>x.id===id);openModal(id?'编辑地点':'添加地点',`<form id="locationForm"><div class="form-grid">${field('地点名称','name',l?.name||'',{required:true,full:true,placeholder:'如：公司 / 学校 / 家'})}${field('备注','note',l?.note||'',{full:true})}</div>${actionsFooter('保存地点')}</form>`,{type:'location',locationId:id});}
function scanForm(){openModal('拍照识别标签',`<p class="modal-intro">适合包装袋、料盘标签及较清晰的丝印。照片发送到你自己的电脑，用 Windows OCR 提取文字，不上传第三方。</p><label class="dropzone photo-drop">${icon('camera')}<b>拍照 / 选择照片</b><span>手机可直接调用相机 · JPG、PNG、WebP</span><input id="scanFile" type="file" accept="image/*" capture="environment" hidden></label><div id="scanProgress"></div><div id="scanResult"></div><div class="note-box">无标签、反光或模糊丝印无法保证识别；电阻色环与电容三位编码不在自动解码范围。识别结果只作草稿，确认后才入库。</div>`,{type:'scan'});}
async function imageData(file){if(file.size>20e6)throw new Error('照片过大，请选择20MB以内的照片');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const ratio=Math.min(1,2400/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.94);}finally{URL.revokeObjectURL(url);}}
async function scanImage(file){const progress=$('#scanProgress');progress.innerHTML='<div class="loading-inline"><span class="spinner"></span>正在读取照片并识别文字…</div>';try{const image=await imageData(file);const r=await api('ocr',{method:'POST',body:{mime:'image/jpeg',content:image.split(',')[1]}});if(modalContext.type!=='scan')return;$('#scanProgress').innerHTML='';$('#scanResult').innerHTML=`<div class="ocr-layout"><img class="ocr-preview" src="${image}" alt="待识别的标签照片"><div class="field"><label for="ocrText">识别原文（可修正）</label><textarea id="ocrText" rows="8">${esc(r.text)}</textarea><small class="helper">识别引擎：Windows OCR。未提供可靠置信度。</small></div></div><div id="ocrFields"></div><div class="modal-actions">${button('重新提取字段','ocr-extract')}${button('核对参数与数量 →','ocr-continue',true)}</div>`;renderOcrFields();}catch(e){if(modalContext.type==='scan'){$('#scanProgress').innerHTML=`<div class="form-error">${esc(e.message)}</div>`;$('#scanResult').innerHTML=`<div class="field"><label for="ocrText">也可手动粘贴标签文字</label><textarea id="ocrText" rows="6"></textarea></div><div id="ocrFields"></div><div class="modal-actions">${button('提取并核对参数 →','ocr-continue',true)}</div>`;}}}
function renderOcrFields(){const p=extractLabel($('#ocrText')?.value||'');$('#ocrFields').innerHTML=`<div class="scan-result"><b>待确认的字段</b><div class="scan-result-grid">${[['型号',p.sku],['封装',p.package],['标称值',p.value],['数量',p.qty],['精度',p.tolerance?p.tolerance+'%':''],['电压',p.voltage]].map(([t,v])=>`<span>${t}：<b>${esc(v||'未识别，请手填')}</b></span>`).join('')}</div></div>`;}
async function toBase64(file){return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(new Error('读取文件失败'));r.readAsDataURL(file);});}
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type});if(window.AndroidDownloads?.saveBase64){const reader=new FileReader();reader.onload=()=>window.AndroidDownloads.saveBase64(name,type,String(reader.result).split(',')[1]||'');reader.readAsDataURL(blob);return;}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function inventoryExportRows(stocks){return [['编号','名称','分类','贴装','封装','参数','标称值','精度','耐压','介质','功率','制造商','立创编号','地点','库位','数量','安全库存'],...stocks.map(st=>{const p=part(st.partId);return [p.sku,p.name,p.category,p.mount,p.package,spec(p),p.value,p.tolerance,p.voltage,p.dielectric,p.power,p.manufacturer,p.lcscCode,locationName(st.locationId),st.bin,st.qty,p.minStock];})];}
function exportInventory(selectedOnly=false){const stocks=selectedOnly?S.stocks.filter(st=>inventorySelected.has(st.id)):S.stocks;if(!stocks.length)throw new Error(selectedOnly?'请先选择要导出的库存':'元件库还没有可导出的库存');download(`元件仓-库存${selectedOnly?'-已选':''}-${new Date().toISOString().slice(0,10)}.csv`,toCsv(inventoryExportRows(stocks)),'text/csv;charset=utf-8');toast(`已导出 ${stocks.length} 个库存库位`);}
function exportBomMaterial(){if(bom.stage!==2||!bom.rows.length)throw new Error('请先导入并核对 BOM');const plan=bomPlan(bom.rows,S,bom.kind,Number(bom.boards),Number(bom.lossRate)),active=new Map(plan.lines.map(x=>[x.rowIndex,x]));const rows=bom.rows.map((r,i)=>{const line=active.get(i),ignored=r.excluded&&!r.forceInclude,st=line?.stock&&!line.stock.draft?S.stocks.find(x=>x.id===line.stock.id):null,p=st?part(st.partId):null;return [r.sku||r.draft?.sku||'',r.value,r.package,r.reference,r.perBoard,bom.boards,ignored?0:line?.total??'',ignored?'自动排除':r.forceInclude&&r.excluded?'强制纳入':'参与库存',ignored?r.excludeReason:'',p?.sku||'',st?locationName(st.locationId):'',st?.bin||''];});download(`${bom.filename.replace(/\.[^.]+$/,'')||'BOM'}-${bom.kind}物料-${new Date().toISOString().slice(0,10)}.csv`,toCsv([['BOM型号','参数','封装','位号','每板用量','板数','本次处理数量','处理状态','排除原因','匹配库存型号','地点','库位'],...rows]),'text/csv;charset=utf-8');toast(`已导出 ${bom.rows.length} 行，其中 ${plan.ignored.length} 行标记为自动排除`);}
async function backup(){const data=await api('backup');download(`元件仓-${space==='demo'?'示例-':''}备份-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2),'application/json');toast('备份已导出');}
async function restorePreview(file){if(file.size>20e6)throw new Error('备份文件最多20MB');const data=JSON.parse(await file.text());const stats=await api('restore/validate',{method:'POST',body:data});restoreFile=data;openModal('核对备份后恢复',`<p class="modal-intro">恢复会用备份替换当前${space==='demo'?'示例库':'真实库'}。恢复前会在电脑自动保留一份当前数据，联网刷新将暂停。</p><div class="restore-summary"><b>${stats.parts} 种元件</b><b>${stats.locations} 个地点</b><b>${stats.stocks} 个库位</b><b>${stats.orders} 笔记录</b></div><p class="note-box">文件：${esc(file.name)}</p><div class="modal-actions">${button('取消','close-modal')}${button('确认恢复此备份','restore-confirm',true)}</div>`,{type:'restore'});}
async function showConnection(){const r=await api('connection');$('#connectionLinks').innerHTML=r.addresses.length?r.addresses.map(x=>`<div class="connection-link"><b>${esc(x.name)}</b><input aria-label="手机访问链接" readonly value="${esc(x.url)}"><button class="text-btn" data-act="copy-connection">复制链接</button></div>`).join(''):'<p class="helper">暂未发现可用的局域网地址，请检查 Wi-Fi 连接。</p>';}
function feedHelp(){openModal('联网数据源接入格式',`<p class="modal-intro">填入一个返回以下 JSON 的 HTTPS 地址。型号必须与库存唯一编号一致，且该元件已开启关注。来源可来自你选择的供应商 API 适配服务。</p><pre class="code-example">${esc(JSON.stringify({items:[{sku:'你的元件编号',source:'供应商或厂商名称',sourceUrl:'https://供应商网站/原始公告',asOf:new Date().toISOString(),price:0.12,currency:'CNY',quantityTier:'100',lifecycle:'active',notice:'原始来源中的消息摘要'}]},null,2))}</pre><p class="helper">生命周期：active 在产、nrnd 不推荐新设计、eol 生命周期结束通知、obsolete 已停产。没有消息时不要填写推测结论。价格与状态可分别提供。</p><p class="helper">应用未附带供应商商业 API 密钥，也不会把普通网页搜索结果当作停产证明。接口未配置时，联网提醒显示“未接入”。</p>`);}
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
async function handleAction(el){const act=el.dataset.act,id=el.dataset.id;if(act.startsWith('team-')||act==='workspace-manage')return teamActionUI(el);
  if(act==='close-modal'){closeModal();return;}
  if(act==='refresh'){await load();toast('库存已刷新');return;}
  if(act==='demo'){space=space==='demo'?'main':'demo';sessionStorage.setItem('component-space',space);loc='';inventorySelected.clear();organize.selected.clear();bom={table:null,mapping:{},rows:[],kind:'出库',boards:1,lossRate:0,locationId:'',bin:'',note:'',stage:0,filename:'',autoExclude:true};closeModal();await load();connectEvents();toast(space==='demo'?'已切换到独立示例库':'已返回真实库存');return;}
  if(!S)return;
  if(act==='watch-add')priceWatchForm();else if(act==='add-part')partForm();else if(act==='edit-part')partForm(id);
  else if(act==='inventory-view')setView('inventory');else if(act==='organize-view')setView('organize');else if(act==='projects-view')setView('projects');else if(act==='storage-view')setView('storage');else if(act==='drafts-view')setView('drafts');
  else if(act==='organize-uniform')organizeUniformForm();else if(act==='organize-all'){$$('[data-organize-row]').forEach(row=>organize.selected.add(row.dataset.organizeRow));render();}else if(act==='organize-clear'){organize.selected.clear();render();}else if(act==='organize-toggle-all'){const ids=organizeCurrentIds(),all=ids.length>0&&ids.every(x=>organize.selected.has(x));ids.forEach(x=>all?organize.selected.delete(x):organize.selected.add(x));render();}
  else if(act==='in')stockForm('入库');else if(act==='out')stockForm('出库');else if(act==='bulk-stock-out')bulkStockOutForm();
  else if(act==='stock-in')stockForm('入库',id);else if(act==='stock-out')stockForm('出库',id);else if(act==='stock-loss')stockForm('损耗',id);else if(act==='stock-count')stockForm('盘点',id);
  else if(act==='transfer'||act==='stock-transfer')transferForm(id);
  else if(act==='detail')detail(id);else if(act==='order-detail')orderDetail(id);else if(act==='price-new')priceForm(id);
  else if(act==='location-new')locationForm();else if(act==='location-edit')locationForm(id);
  else if(act==='tolerance')$('#f-tolerance').value=el.dataset.value;
  else if(act==='scan')scanForm();else if(act==='scan-hub')scanHub();else if(act==='qr-scan')scanHub();
  else if(act==='qr-open-manual')openQrCode($('#qrManual').value);
  else if(act==='part-label'){const p=part(id);qrLabel('part',p.id,p.sku,[spec(p),primaryStock(p.id)?.bin].filter(Boolean).join(' · '));}
  else if(act==='container-label'){const box=S.containers.find(x=>x.id===activeContainerId);qrLabel('container',box.id,box.name,`${locationName(box.locationId)} · ${box.rows}×${box.cols}`);}
  else if(act==='label-download')download(modalContext.name,modalContext.svg,'image/svg+xml;charset=utf-8');
  else if(act==='ocr-extract')renderOcrFields();
  else if(act==='ocr-continue'){const p=extractLabel($('#ocrText')?.value||'');if(!p.description.trim())throw new Error('请先拍照识别，或填写标签文字');const exists=S.parts.find(x=>x.sku.toLowerCase()===p.sku.toLowerCase());if(exists){const st=S.stocks.find(s=>s.partId===exists.id&&(!loc||s.locationId===loc))||S.stocks.find(s=>s.partId===exists.id);stockForm('入库',st?.id,{qty:p.qty||'',note:'照片识别后人工确认'});toast('找到已有型号，请核对数量和存放地点');}else partForm('',{...p,qty:p.qty||0,ocr:true});}
  else if(act==='bom-view')setView('bom');
  else if(act==='bom-template')download('元件仓-BOM模板.csv',toCsv([['型号','每板用量','封装','参数','耐压','精度','介质','位号','手动损耗'],['R-10K-0603',4,'0603','10kΩ','','1%','','R1 R2 R3 R4',0],['C-100N-0603',6,'0603','100nF','50V','10%','X7R','C1 C2 C3 C4 C5 C6',0]]),'text/csv;charset=utf-8');
  else if(act==='bom-parse'){const rows=parseDelimited($('#bomPaste').value);if(rows.length<2)throw new Error('请粘贴表头和至少一行数据');if(rows.length>1001)throw new Error('一次最多1000行元件');bom.table=rows;bom.mapping=guessColumns(rows[0]);bom.filename='粘贴的 BOM';bom.stage=1;render();}
  else if(act==='bom-map'){for(const key of ['sku','qty','value','package','voltage','tolerance','dielectric','reference','loss'])bom.mapping[key]=Number($('#f-map-'+key).value);bom.rows=rowsToBom(bom.table,bom.mapping,{autoExclude:bom.autoExclude});bom.locationId=loc||S.locations[0].id;bom.stage=2;mapBom();render();}
  else if(act==='bom-reset'){bom.stage=0;bom.rows=[];bom.table=null;render();}
  else if(act==='bom-new-part'){const row=bom.rows[Number(el.dataset.index)];partForm('',{sku:row.sku,name:row.sku||row.value,value:row.value,package:row.package,qty:0,locationId:bom.locationId,fromBom:Number(el.dataset.index)});}
  else if(act==='bom-toggle-excluded'){const index=Number(el.dataset.index);if(bom.rows[index]){bom.rows[index].forceInclude=!bom.rows[index].forceInclude;mapBom();render();}}
  else if(act==='bom-include-all-excluded'){bom.rows.filter(r=>r.excluded).forEach(r=>r.forceInclude=true);mapBom();render();toast('已强制纳入全部自动排除项，请逐项确认库存匹配');}
  else if(act==='bom-restore-excluded'){bom.rows.filter(r=>r.excluded).forEach(r=>r.forceInclude=false);mapBom();render();toast('已恢复自动排除，非焊接项目不参与库存');}
  else if(act==='bom-export')exportBomMaterial();
  else if(act==='bom-save-project')projectFromBom();
  else if(act==='bom-confirm'){const p=bomPlan(bom.rows,S,bom.kind,Number(bom.boards),Number(bom.lossRate));if(p.errors.length)throw new Error(p.errors[0]);openModal(`确认 BOM ${bom.kind}`,`<p class="modal-intro">请确认以下批次信息。提交后将统一更新库存并生成可追溯的流水。BOM入库只适用于仍可再次领用的散料，自动排除的螺丝、测试点等不会参与扣账。</p><div class="restore-summary"><b>${p.lines.length} 行物料</b><b>${p.ignored.length} 行已排除</b><b>${bom.boards} 块板</b><b>${num(p.total)} 个${bom.kind==='入库'?'入库':'扣减'}</b><b>${esc(locationName(bom.locationId))}</b></div><div class="note-box">${esc(bom.note||'未填写项目备注')}</div><div class="modal-actions">${button('返回核对','close-modal')}${button('确认提交','bom-submit',true)}</div>`,{type:'bom-confirm',requestId:uid()});}
  else if(act==='bom-submit'){const rows=bom.rows.filter(r=>!(r.excluded&&!r.forceInclude));await mutate({type:'bom.post',kind:bom.kind,boards:Number(bom.boards),lossRate:Number(bom.lossRate),locationId:bom.locationId,bin:bom.bin||'',rows:rows.map(r=>({...r.stockId?.startsWith('new:')?{partId:r.stockId.slice(4),bin:bom.bin||''}:r.autoCreate?{autoPart:r.draft,bin:bom.bin||''}:{stockId:r.stockId},excluded:r.excluded,forceInclude:r.forceInclude,perBoard:r.perBoard,loss:r.loss,reference:r.reference})),note:bom.note},modalContext.requestId);closeModal();bom.stage=0;bom.rows=[];bom.table=null;setView('transactions');toast('BOM整单已提交，库存与流水已保存');}
  else if(act==='project-new')projectForm();else if(act==='project-edit')projectForm(activeProjectId);
  else if(act==='project-reserve'){await mutate({type:'project.reserve',projectId:activeProjectId,boards:projectBoards,lossRate:projectRate});toast('项目元件已预留，其他项目可用量已更新');}
  else if(act==='project-release'){await mutate({type:'project.release',projectId:activeProjectId});toast('项目预留已释放');}
  else if(act==='project-issue'){const project=S.projects.find(x=>x.id===activeProjectId),a=projectAnalysis(project,S,projectBoards,projectRate);if(!a.complete)throw new Error('当前库存不足，不能整单领料');openModal('确认项目领料出库',`<p class="modal-intro">将为 ${esc(project.name)} ${esc(project.version)} 实际领用 ${projectBoards} 块所需元件，并同步释放相应预留。</p><div class="restore-summary"><b>${a.lines.length} 种元件</b><b>${a.lines.reduce((n,x)=>n+x.required,0)} 个</b><b>损耗率 ${projectRate}%</b><b>实物库存将扣减</b></div><div class="modal-actions">${button('返回','close-modal')}${button('确认领料','project-issue-submit',true)}</div>`,{requestId:uid(),projectId:project.id});}
  else if(act==='project-issue-submit'){await mutate({type:'project.issue',projectId:modalContext.projectId,boards:projectBoards,lossRate:projectRate,note:`项目领料 ${projectBoards} 块`},modalContext.requestId);closeModal();setView('transactions');toast('项目领料已出库，预留已同步释放');}
  else if(act==='project-pick'||act==='project-shortage'){const project=S.projects.find(x=>x.id===activeProjectId),a=projectAnalysis(project,S,projectBoards,projectRate),rows=act==='project-shortage'?a.shortages:a.lines;download(`${project.name}-${act==='project-shortage'?'缺料清单':'拣料单'}.csv`,toCsv([['型号','每板用量','目标数量','可用','缺少','地点与库位'],...rows.map(x=>[x.part.sku,x.perBoard,x.required,x.available,x.shortage,x.pickups.map(y=>`${locationName(y.locationId)}/${y.bin||'未分配'}:${y.qty}`).join('；')])]),'text/csv;charset=utf-8');}
  else if(act==='project-procure'){const project=S.projects.find(x=>x.id===activeProjectId),a=projectAnalysis(project,S,projectBoards,projectRate);await mutate({type:'procurement.bulkAdd',items:a.shortages.map(x=>({partId:x.partId,projectId:project.id,requiredQty:x.shortage,note:`${project.name} ${project.version} · ${projectBoards}块缺料`}))});setView('procurement');toast('项目缺料已加入采购清单');}
  else if(act==='finished-new')finishedForm(activeProjectId);
  else if(act==='purchase-new')purchaseForm();else if(act==='purchase-part')purchaseForm(id,'',Number(el.dataset.qty));else if(act==='purchase-edit'){const item=S.procurementItems.find(x=>x.id===id);purchaseForm(item.partId,item.id);}else if(act==='purchase-receive')receiveForm(id);
  else if(act==='usage-new')usageForm(id);else if(act==='substitution-new')substitutionForm(id);
  else if(act==='container-new')containerForm();else if(act==='container-assign')assignContainer();else if(act==='container-assign-cell')assignContainer(el.dataset.cell);else if(act==='container-stocktake')containerStocktakeForm();
  else if(act==='draft-delete'){saveDrafts(drafts().filter(x=>x.id!==id));render();toast('草稿已删除');}
  else if(act==='draft-review'){await load(false);const d=drafts().find(x=>x.id===id),st=S.stocks.find(x=>x.id===d.stockId);if(!d||!st)throw new Error('草稿对应库位已不存在，请删除后重新登记');openModal('核对待同步草稿',`<p class="modal-intro">请根据电脑最新库存核对后再提交。系统不会自动扣账。</p><div class="restore-summary"><b>记录时 ${d.snapshotQty} 个</b><b>现在 ${st.qty} 个</b><b>${d.kind}</b><b>${d.kind==='出库'?d.qty*d.boards+d.loss:d.qty} 个</b></div><div class="note-box">${esc(d.note||'未填备注')}</div><div class="modal-actions">${button('返回','close-modal')}${button('确认提交','draft-submit',true,`data-id="${d.id}"`)}</div>`,{requestId:uid()});}
  else if(act==='draft-submit'){const d=drafts().find(x=>x.id===id);await mutate({type:'stock.post',kind:d.kind,stockId:d.stockId,qty:d.qty,boards:d.boards,loss:d.loss,note:d.note},modalContext.requestId);saveDrafts(drafts().filter(x=>x.id!==id));closeModal();render();toast('草稿已提交，确认库存已更新');}
  else if(act==='undo-confirm')openModal('确认撤销此批次',`<p class="modal-intro">撤销会恢复这一批次的库存变化，并保留反向流水。若库位已有后续记录，系统会阻止撤销。</p><div class="modal-actions">${button('取消','close-modal')}${button('确认撤销','undo-run',true,`data-id="${id}"`)}</div>`,{requestId:uid()});
  else if(act==='undo-run'){await mutate({type:'order.undo',orderId:id},modalContext.requestId);closeModal();toast('已撤销，并生成反向流水');}
  else if(act==='backup')await backup();
  else if(act==='restore-confirm'){const r=await api('restore',{method:'POST',body:{backup:restoreFile,rev:S.rev,requestId:modalContext.requestId||uid()}});if(r.pending){closeModal();toast('恢复申请已提交，等待另一位管理员审批');return;}acceptState(r.state);restoreFile=null;closeModal();render();toast('备份已恢复，原数据已自动备份');}
  else if(act==='connection')await showConnection();
  else if(act==='copy-connection'){const input=el.parentElement.querySelector('input');try{await navigator.clipboard.writeText(input.value);toast('配对链接已复制，请只发给你自己的设备');}catch{input.focus();input.select();toast('链接已选中，请手动复制');}}
  else if(act==='export-inventory')exportInventory(false);else if(act==='export-inventory-selected')exportInventory(true);else if(act==='inventory-clear'){inventorySelected.clear();render();}
  else if(act==='export-events')download('元件仓-流水.csv',toCsv([['时间','批次','类型','型号','地点','库位','操作前','变化','操作后','备注'],...S.events.map(e=>[e.time,e.orderId,e.type,part(e.partId)?.sku,locationName(e.locationId),e.bin,e.before,e.delta,e.after,e.note])]),'text/csv;charset=utf-8');
  else if(act==='feed-help')feedHelp();
  else if(act==='lcsc-refresh'){toast('正在读取立创商城阶梯价格…');try{const r=await api('lcsc/refresh',{method:'POST',body:{}});acceptState(r.state);render();toast(`已检查 ${r.checked} 种元件，记录 ${r.matched} 条价格变化${r.failed?`，${r.failed} 种读取失败`:''}`);}catch(e){await load();throw e;}}
  else if(act==='feed-refresh'){toast('正在读取其他数据源…');try{const r=await api('feed/refresh',{method:'POST',body:{}});acceptState(r.state);render();toast(`同步完成，新增 ${r.matched} 条有来源记录`);}catch(e){await load();throw e;}}
  else if(act==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else openModal('添加到桌面',`<p class="modal-intro">电脑：使用 Edge / Chrome 打开公网 HTTPS 地址，选择浏览器菜单中的“安装此网站为应用”。</p><p>手机：用手机打开同一个 HTTPS 地址，使用浏览器菜单中的“添加到主屏幕”或“安装应用”。安装后的图标仍连接同一份库存，换 Wi-Fi 或使用移动数据都可以继续查看和操作。</p><div class="note-box">${remoteAccess?'库存保存在你的电脑中；电脑在线并运行元件仓时，已打开的设备会实时收到更新。':'库存由当前服务端保存，已打开的设备会实时收到更新。'}网络短暂中断后会自动重连并重新读取最新库存。请把 HTTPS 地址当作自己的私人入口，不要公开转发。</div>`);}
}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return;}const project=e.target.closest('[data-project]');if(project){activeProjectId=project.dataset.project;render();return;}const lp=e.target.closest('[data-location]');if(lp){loc=lp.dataset.location;render();return;}const kind=e.target.closest('[data-bom-kind]');if(kind){bom.kind=kind.dataset.bomKind;mapBom();renderBomRows();render();return;}const el=e.target.closest('[data-act]');if(!el||el.disabled)return;e.preventDefault();el.disabled=true;try{await handleAction(el);}catch(error){if($('#dialog').open)errorInModal(error.message);else toast(error.message,true);}finally{if(el.isConnected)el.disabled=false;}});
$('#menuBtn').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#sidebarClose').addEventListener('click',()=>$('#sidebar').classList.remove('open'));
$('#sidebarBackdrop').addEventListener('click',()=>$('#sidebar').classList.remove('open'));
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar').classList.remove('open');});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function syncInventorySelection(){const rows=inventoryCurrentStocks(),all=rows.length>0&&rows.every(st=>inventorySelected.has(st.id));$$('#inventorySelectAll,.inventory-select-all').forEach(x=>{x.checked=all;x.indeterminate=!all&&rows.some(st=>inventorySelected.has(st.id));});const label=$('#inventorySelectLabel');if(label)label.textContent=`全选当前结果（${rows.length}）`;}
function syncOrganizeSelection(){const ids=organizeCurrentIds(),all=ids.length>0&&ids.every(id=>organize.selected.has(id));$$('#organizeSelectAll,.organize-select-all').forEach(x=>{x.checked=all;x.indeterminate=!all&&ids.some(id=>organize.selected.has(id));});const label=$('#organizeSelectLabel');if(label)label.textContent=`全选当前结果（${ids.length}）`;}
document.addEventListener('input',e=>{const t=e.target;if(t.id==='inventorySearch'){filter.q=t.value;$('#inventoryBody').innerHTML=inventoryRows();syncInventorySelection();}if(t.id==='organizeSearch'){organize.q=t.value;$('#organizeBody').innerHTML=organizeRows();syncOrganizeSelection();}if(t.id==='storageSearch'){storageQuery=t.value;render();$('#storageSearch')?.focus();}if(t.id==='txSearch')$('#transactionBody').innerHTML=transactionRows(t.value);if(t.closest('#stockForm'))updateStockCalculation();if(t.id==='bomNote')bom.note=t.value;});
document.addEventListener('change',async e=>{const t=e.target;try{
  if(t.id==='categoryFilter'){filter.category=t.value;render();}if(t.id==='mountFilter'){filter.mount=t.value;render();}if(t.id==='lowFilter'){filter.low=t.checked;render();}
  if(t.id==='inventorySelectAll'||t.classList.contains('inventory-select-all')){inventoryCurrentStocks().forEach(st=>t.checked?inventorySelected.add(st.id):inventorySelected.delete(st.id));render();}if(t.classList.contains('inventory-check')){t.checked?inventorySelected.add(t.dataset.id):inventorySelected.delete(t.dataset.id);render();}
  if(t.id==='pendingFilter'){organize.pending=t.checked;render();}if(t.id==='organizeSelectAll'||t.classList.contains('organize-select-all')){organizeCurrentIds().forEach(id=>t.checked?organize.selected.add(id):organize.selected.delete(id));render();}if(t.classList.contains('organize-check')){t.checked?organize.selected.add(t.dataset.id):organize.selected.delete(t.dataset.id);syncOrganizeSelection();}
  if(t.id==='projectBoards'){projectBoards=Number(t.value);render();}if(t.id==='projectRate'){projectRate=Number(t.value);render();}if(t.id==='containerSelect'){activeContainerId=t.value;render();}
  if(t.id==='bomFile'&&t.files[0]){toast('正在解析BOM文件…');const r=await api('bom/parse',{method:'POST',body:{name:t.files[0].name,content:await toBase64(t.files[0])}});if(r.rows.length<2)throw new Error('BOM需要包含表头和至少一行数据');bom.table=r.rows;bom.mapping=guessColumns(r.rows[0]);bom.filename=t.files[0].name;bom.stage=1;render();}
  if(t.id==='scanFile'&&t.files[0])await scanImage(t.files[0]);
  if(t.id==='qrScanFile'&&t.files[0])await decodeQrFile(t.files[0]);
  if(t.id==='restoreInput'&&t.files[0]){await restorePreview(t.files[0]);t.value='';}
  if(t.id==='bomAutoExclude'){bom.autoExclude=t.checked;if(bom.table&&bom.stage>=1){bom.rows=rowsToBom(bom.table,bom.mapping,{autoExclude:bom.autoExclude});if(bom.stage===2){mapBom();}render();}}if(t.id==='bomKind'){bom.kind=t.value;mapBom();render();}if(t.id==='bomLocation'){bom.locationId=t.value;mapBom();renderBomRows();}if(t.id==='bomBoards'){bom.boards=Number(t.value);renderBomRows();}if(t.id==='bomRate'){bom.lossRate=Number(t.value);renderBomRows();}if(t.id==='bomBin'){bom.bin=t.value;renderBomRows();}
  if(t.classList.contains('bom-match')){bom.rows[Number(t.dataset.row)].stockId=t.value;renderBomRows();}if(t.classList.contains('bom-qty')){bom.rows[Number(t.dataset.row)].perBoard=Number(t.value);renderBomRows();}if(t.classList.contains('bom-loss')){bom.rows[Number(t.dataset.row)].loss=Number(t.value);renderBomRows();}
}catch(error){toast(error.message,true);}});
document.addEventListener('submit',async e=>{const form=e.target;if(form.dataset.teamForm){e.preventDefault();await teamSubmit(e);return;}if(!['partForm','watchPartForm','stockForm','bulkStockOutForm','transferForm','locationForm','priceForm','settingsForm','pairForm','organizeForm','bulkOrganizeForm','projectForm','purchaseForm','receiveForm','usageForm','substitutionForm','containerForm','containerAssignForm','containerStocktakeForm','finishedForm'].includes(form.id))return;e.preventDefault();const submit=form.querySelector('[type="submit"]');if(submit.disabled)return;submit.disabled=true;const d=Object.fromEntries(new FormData(form));const ctx={...modalContext};form.dataset.requestId||=uid();try{
  if(form.id==='partForm'){const r=await mutate({type:'part.save',part:{...ctx.existing,...d,id:ctx.partId||undefined,watch:d.watch==='on'},qty:d.qty??0,locationId:d.locationId,bin:d.bin},form.dataset.requestId);if(ctx.fromBom!==undefined){const st=S.stocks.find(s=>s.partId===r.partId&&s.locationId===bom.locationId);if(st)bom.rows[ctx.fromBom].stockId=st.id;render();}closeModal();toast(ctx.partId?'参数已保存':'元件已保存，库存已记录');}
  if(form.id==='watchPartForm'){const existing=S.parts.find(p=>p.sku.toLowerCase()===d.sku.trim().toLowerCase());await mutate({type:'part.save',skipStock:!existing,part:{...existing,id:existing?.id,sku:d.sku.trim(),name:d.name.trim()||existing?.name||d.sku.trim(),manufacturer:d.manufacturer.trim()||existing?.manufacturer||'',lcscCode:d.lcscCode.trim(),category:existing?.category||'IC',mount:d.mount||existing?.mount||'贴片',package:d.package.trim()||existing?.package||'',minStock:existing?.minStock||0,watch:true,datasheetUrl:d.datasheetUrl.trim()||existing?.datasheetUrl||'',purchaseUrl:existing?.purchaseUrl||'',description:existing?.description||'仅用于立创商城价格关注'},qty:0},form.dataset.requestId);closeModal();toast(existing?'已为现有元件开启立创价格关注':'已添加IC价格关注');}
  if(form.id==='stockForm'){if(currentRole==='readonly')throw new Error('只读成员不能记录出入库');if(!online){const st=S.stocks.find(x=>x.id===d.stockId);if(!st||!['出库','损耗','盘点'].includes(ctx.kind))throw new Error('离线草稿只支持已有库位的领用、损耗和盘点');const list=drafts();list.push({id:uid(),kind:ctx.kind,stockId:d.stockId,qty:Number(d.qty),boards:Number(d.boards||1),loss:Number(d.loss||0),note:d.note||'',createdAt:new Date().toISOString(),snapshotRev:S.rev,snapshotQty:st.qty});saveDrafts(list);closeModal();setView('drafts');toast('已保存为待同步草稿，确认库存没有改变');}else{await mutate({type:'stock.post',kind:ctx.kind,...d},form.dataset.requestId);closeModal();toast(`${ctx.kind}已保存`);}}
  if(form.id==='bulkStockOutForm'){if(!online)throw new Error('批量出库需要电脑在线，以确保整批原子提交');const rows=(ctx.stocks||[]).map(st=>({stockId:st.id,qty:st.qty})).filter(x=>x.qty>0);if(!rows.length)throw new Error('选中的库位已没有库存，请刷新后重试');await mutate({type:'stock.bulkPost',kind:'出库',rows,note:d.note},form.dataset.requestId);inventorySelected.clear();closeModal();toast(`已批量出库 ${rows.length} 个库位`);}
  if(form.id==='transferForm'){await mutate({type:'stock.transfer',...d},form.dataset.requestId);closeModal();toast('调拨完成，两端库位已同时更新');}
  if(form.id==='locationForm'){await mutate({type:'location.save',id:ctx.locationId,...d},form.dataset.requestId);closeModal();toast('地点已保存');}
  if(form.id==='priceForm'){await mutate({type:'price.record',partId:ctx.partId,...d},form.dataset.requestId);closeModal();toast('价格记录已保存');}
  if(form.id==='settingsForm'){await mutate({type:'settings.save',...d,lcscEnabled:d.lcscEnabled==='on',feedEnabled:d.feedEnabled==='on'},form.dataset.requestId);toast('设置已保存');}
  if(form.id==='pairForm'){await api('auth',{method:'POST',body:{key:d.key.trim()},auth:true});await load();}
  if(form.id==='organizeForm'){const updates=$$('[data-organize-row]').map(row=>{const p={};row.querySelectorAll('[data-field]').forEach(x=>p[x.dataset.field]=x.type==='number'?Number(x.value):x.value);const locationId=row.querySelector('[data-stock-field="locationId"]')?.value||'',bin=row.querySelector('[data-stock-field="bin"]')?.value??'';return {partId:row.dataset.organizeRow,part:p,stockId:row.dataset.stockId||'',...(row.dataset.stockId&&locationId?{locationId,bin}:{})};});if(!updates.length)throw new Error('当前没有可保存的元件');await mutate({type:'parts.bulkUpdate',updates},form.dataset.requestId);toast(`已保存 ${updates.length} 条元件资料`);}
  if(form.id==='bulkOrganizeForm'){const patch={};for(const key of ['category','mount','package'])if(d[key]!==undefined&&d[key]!=='')patch[key]=d[key];if(d.minStock!=='')patch.minStock=Number(d.minStock);const updates=[...organize.selected].map(partId=>{const st=primaryStock(partId);return {partId,part:patch,...(st&&(d.locationId||d.bin)?{stockId:st.id,locationId:d.locationId||st.locationId,bin:d.bin||st.bin}:{})};});await mutate({type:'parts.bulkUpdate',updates},form.dataset.requestId);closeModal();organize.selected.clear();toast(`已统一更新 ${updates.length} 条元件`);}
  if(form.id==='projectForm'){const table=parseDelimited(`型号,每板用量,位号\n${d.rows}`),rows=table.slice(1).map((r,i)=>{const p=S.parts.find(x=>x.sku.toLowerCase()===String(r[0]||'').trim().toLowerCase());if(!p)throw new Error(`第${i+1}行型号未在元件库建档：${r[0]||'空'}`);return {partId:p.id,perBoard:Number(r[1]),reference:String(r[2]||'').trim()};});const out=await mutate({type:'project.save',project:{id:ctx.projectId||undefined,name:d.name,version:d.version,previousProjectId:d.previousProjectId,note:d.note,rows}},form.dataset.requestId);activeProjectId=out.projectId;closeModal();setView('projects');toast('项目BOM已保存');}
  if(form.id==='purchaseForm'){await mutate({type:'procurement.save',item:{id:ctx.itemId||undefined,...d,requiredQty:Number(d.requiredQty),orderedQty:Number(d.orderedQty),moq:Number(d.moq),packMultiple:Number(d.packMultiple)}},form.dataset.requestId);closeModal();toast('采购项已保存');}
  if(form.id==='receiveForm'){await mutate({type:'procurement.receive',itemId:ctx.itemId,...d,qty:Number(d.qty)},form.dataset.requestId);closeModal();toast('到货已入库，采购进度已更新');}
  if(form.id==='usageForm'){await mutate({type:'usage.record',partId:ctx.partId,...d},form.dataset.requestId);closeModal();detail(ctx.partId);toast('实测使用记录已保存');}
  if(form.id==='substitutionForm'){await mutate({type:'substitution.save',partId:ctx.partId,...d},form.dataset.requestId);closeModal();detail(ctx.partId);toast('替代料关系已保存');}
  if(form.id==='containerForm'){const out=await mutate({type:'container.save',container:{id:ctx.containerId||undefined,...d,rows:Number(d.rows),cols:Number(d.cols)}},form.dataset.requestId);activeContainerId=out.containerId;closeModal();setView('storage');toast('元件盒已保存');}
  if(form.id==='containerAssignForm'){await mutate({type:'container.assign',containerId:ctx.containerId,...d},form.dataset.requestId);closeModal();render();toast('元件已放入格位');}
  if(form.id==='containerStocktakeForm'){const counts=ctx.stocks.map(stockId=>({stockId,qty:Number(d['count-'+stockId])}));await mutate({type:'container.stocktake',containerId:ctx.containerId,counts,note:d.note},form.dataset.requestId);closeModal();render();toast('元件盒盘点差异已统一提交');}
  if(form.id==='finishedForm'){await mutate({type:'finishedGood.post',projectId:ctx.projectId,...d,qty:Number(d.qty)},form.dataset.requestId);closeModal();render();toast('板卡 / 成品库存已更新');}
}catch(error){if($('#dialog').open)errorInModal(error.message);else toast(error.message,true);}finally{if(submit.isConnected)submit.disabled=false;}});
async function initialize(){
  if(location.hash.startsWith('#share=')){await showSharedInventory(location.hash.slice(7));return;}
  const h=location.hash.slice(1);if(titles[h])view=h;
  restoreLastSnapshot();
  try{await refreshIdentity();space=T.workspaces.some(w=>w.id===space)?space:T.workspaces[0]?.id;await load();connectEvents();}
  catch(e){if(e.network){try{const last=JSON.parse(localStorage.getItem('team-last-user')||'null');if(last){T.user=last.user;T.workspaces=last.workspaces;space=last.space;const cached=JSON.parse(localStorage.getItem(cacheKey('cache'))||'null');if(cached){S=cached;currentRole=S.access?.role||'readonly';render();setConnection(false);return;}}}catch{}}clearIdentity();showAuthScreen(e.status===401?'':e.message);}
  if('serviceWorker' in navigator&&window.isSecureContext&&!/ComponentHubAndroid\//.test(navigator.userAgent))navigator.serviceWorker.register('/sw.js').catch(()=>{});
}
setInterval(()=>{if(T.user&&S&&!document.hidden&&!$('#dialog').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))load(false).then(r=>{if(Number($('#page').dataset.rev)!==r.state.rev){$('#page').dataset.rev=r.state.rev;render();}}).catch(()=>{});},30000);
async function refreshWhenAvailable(){
  if(!T.user||document.hidden||$('#dialog').open)return;
  try{
    const previousRev=S?.rev;
    await load(false);
    if(S?.rev!==previousRev)render();
    connectEvents();
  }catch{}
}
window.addEventListener('online',refreshWhenAvailable);
window.addEventListener('focus',refreshWhenAvailable);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshWhenAvailable();});
window.addEventListener('hashchange',()=>{if(titles[location.hash.slice(1)])setView(location.hash.slice(1));});

function roleName(role){return role==='owner'?'所有者':role==='admin'?'管理员':role==='member'?'可出入库成员':'只读成员';}
function purgeCache(id){for(const k of Object.keys(localStorage)){if(k.includes('-'+id+'-'))localStorage.removeItem(k);}}
async function teamLoad(){if(!T.user)return;T.team=await api('team');return T.team;}
async function showSharedInventory(key){try{const r=await fetch('/api/share',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key})});const d=await r.json();if(!r.ok)throw Error(d.error);document.body.innerHTML=`<main class="content-wrap" style="max-width:1000px;margin:auto;padding:32px"><h1>${esc(d.name)}</h1><p>只读分享 · 截止 ${time(d.expiresAt)}</p><div class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>型号</th><th>分类</th><th>参数</th><th>数量</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.sku)}<br><small>${esc(x.name)}</small></td><td>${esc(x.category)}</td><td>${esc([x.value,x.package].filter(Boolean).join(' · '))}</td><td>${num(x.qty)}</td></tr>`).join('')}</tbody></table></div></div></main>`;}catch(e){document.body.innerHTML=`<main class="content-wrap" style="max-width:640px;margin:auto;padding:32px"><div class="panel"><h2>分享链接不可用</h2><p>${esc(e.message)}</p></div></main>`;}}
const teamLabels={'part.save':'保存元件','parts.bulkUpdate':'批量整理','location.save':'修改地点','settings.save':'修改设置','stock.post':'手动记账','stock.bulkPost':'批量出库','bom.post':'BOM记账','project.save':'保存项目','project.reserve':'项目预留','project.release':'释放预留','project.issue':'项目领料','procurement.save':'保存采购','procurement.bulkAdd':'新增采购','procurement.receive':'确认到货','procurement.cancel':'取消采购','library.create':'创建元件库','library.restore':'恢复备份','legacy.import':'迁移旧库存','library.rename':'修改库名','policy.save':'修改审批规则','invite.create':'生成邀请','invite.join':'接受邀请','invite.revoke':'撤销邀请','member.save':'调整成员权限','member.remove':'移除成员','request.review':'处理加入申请','share.create':'创建只读分享','share.revoke':'撤销分享','backup.create':'创建库备份','procurement.assign':'分配采购任务','approval.request':'提交审批','approval.approve':'批准申请','approval.reject':'驳回申请','library.transfer.out':'跨库调出','library.transfer.in':'跨库调入','order.undo':'撤销流水','container.stocktake':'元件盒盘点','finishedGood.post':'板卡记账'};
const statusName=v=>({pending:'待处理',approved:'已批准',rejected:'已驳回',approve:'批准',reject:'驳回'}[v]||v);
const teamManager=()=>['owner','admin'].includes(currentRole);
const tform=(kind,html,label='保存')=>`<form data-team-form="${kind}">${html}${actionsFooter(label)}</form>`;
function restoreLastSnapshot(){try{const last=JSON.parse(localStorage.getItem('team-last-user')||'null');if(!last?.user||!last?.space)return false;const cached=JSON.parse(localStorage.getItem('team-v2-'+last.user.id+'-'+last.space+'-cache')||'null');if(!cached)return false;T.user=last.user;T.workspaces=last.workspaces;space=last.space;S=cached;currentRole=S.access?.role||'readonly';setConnection(false);render();return true;}catch{return false;}}
function scopeFields(m={locations:null,projects:null}){return `<div class="note-box">地点权限控制库存数量、库位和操作范围；元件型号资料在同一个库内共享。管理员拥有全库权限。</div>${selectField('地点范围','locationMode',['全部地点','指定地点'],m.locations===null?'全部地点':'指定地点')}<div class="scope-options">${S.locations.map(l=>`<label><input type="checkbox" name="locScope" value="${l.id}" ${m.locations?.includes(l.id)?'checked':''}>${esc(l.name)}</label>`).join('')}</div>${selectField('项目范围','projectMode',['全部项目','指定项目'],m.projects===null?'全部项目':'指定项目')}<div class="scope-options">${S.projects.map(p=>`<label>${esc(p.name)}<select name="proj-${p.id}"><option value="">无权限</option><option value="readonly" ${m.projects?.find(x=>x.id===p.id)?.role==='readonly'?'selected':''}>只读</option><option value="member" ${m.projects?.find(x=>x.id===p.id)?.role==='member'?'selected':''}>可操作</option></select></label>`).join('')||'<small>当前库还没有项目</small>'}</div>`;}
function scopeData(fd){return {locations:fd.get('locationMode')==='指定地点'?fd.getAll('locScope'):null,projects:fd.get('projectMode')==='指定项目'?S.projects.map(p=>({id:p.id,role:fd.get('proj-'+p.id)})).filter(x=>x.role):null};}
function showAuthScreen(message=''){S=null;eventStream?.close();$('#navigation').innerHTML='';$('#workspaceName').textContent='请登录';$('#workspaceRole').textContent='账号';$('#demoSwitch').textContent='元件仓 2.0 测试版';$('#offlineBanner').hidden=true;$('#page').innerHTML=`<div class="panel login-panel"><p class="eyebrow">元件仓 · 多人测试版</p><h1>每个人的库存，共同的项目</h1><p class="subtle">注册后拥有独立的“我的库存”，再通过邀请码加入学校或项目组的元件库。</p>${message?`<p class="form-error">${esc(message)}</p>`:''}${window.AndroidDownloads?.changeServer?button('修改服务器地址','team-server'):''}${tform('account',`${field('账号','username','',{required:true})}${field('密码（8～128位）','password','',{required:true,type:'password'})}<div class="field"><label for="accountMode">操作</label><select id="accountMode" name="mode"><option value="login">登录已有账号</option><option value="register">注册新账号</option></select></div>`,'继续')}<p class="helper">新账号的库存为空。你的旧库存需由你在电脑上登录后，预览并确认迁移，不会自动复制给其他人。</p></div>`;}
function resetWorkspaceState(){loc='';filter={q:'',category:'',mount:'',low:false};inventorySelected.clear();organize={q:'',pending:true,selected:new Set()};activeProjectId='';activeContainerId='';storageQuery='';restoreFile=null;T.team=null;bom={table:null,mapping:{},rows:[],kind:'出库',boards:1,lossRate:0,locationId:'',bin:'',note:'',stage:0,filename:'',autoExclude:true};}
function purgeUserData(){if(T.user)for(const k of Object.keys(localStorage))if(k.startsWith('team-v2-'+T.user.id+'-'))localStorage.removeItem(k);localStorage.removeItem('team-last-user');}
function clearIdentity(){purgeUserData();T={user:null,workspaces:[],team:null,epoch:T.epoch+1};S=null;eventStream?.close();resetWorkspaceState();closeModal();sessionStorage.removeItem('component-space');}
async function refreshIdentity(){const r=await api('auth/me',{auth:true});const old=T.workspaces||[];T.user=r.user;T.workspaces=r.workspaces||[];for(const w of old){const next=T.workspaces.find(x=>x.id===w.id);if(!next||JSON.stringify({r:w.role,l:w.locations,p:w.projects})!==JSON.stringify(next&&{r:next.role,l:next.locations,p:next.projects})){purgeCache(w.id);if(w.id===space){S=null;closeModal();resetWorkspaceState();}}}localStorage.setItem('team-last-user',JSON.stringify({user:T.user,workspaces:T.workspaces,space}));return r;}
async function switchWorkspace(id){if(!T.workspaces.some(x=>x.id===id))throw new Error('没有访问这个元件库的权限');T.epoch++;eventStream?.close();closeModal();resetWorkspaceState();space=id;S=null;sessionStorage.setItem('component-space',space);$('#page').innerHTML='<div class="loading-state">正在切换元件库…</div>';await load();localStorage.setItem('team-last-user',JSON.stringify({user:T.user,workspaces:T.workspaces,space}));connectEvents();}
function teamView(){if(!T.team)return `${header('协作中心','成员与协作','正在读取当前库的成员与操作记录…')}`;const t=T.team,w=t.workspace,mgr=teamManager();return `${header('协作中心',esc(w.name),`账号 ${esc(T.user.username)} · ${roleName(currentRole)}`,button('切换库 / 退出','team-switch')+button('刷新','team-refresh'))}
  <div class="note-box">库编号：<b>${esc(space)}</b> ${button('复制库编号','team-copy-id')}<small>朋友可使用编号申请加入。预留不扣实物；实际出库会保护其他项目的预留数量。</small></div>
  <div class="team-grid"><section class="panel"><div class="panel-head"><h2>成员与范围</h2>${mgr?button('邀请成员','team-invite',true):''}</div>${t.members.map(m=>`<div class="list-row"><span><b>${esc(m.username)} ${m.userId===T.user.id?'（我）':''}</b><small>${roleName(m.role)}${mgr?` · ${m.locations===null?'全部地点':`${m.locations?.length||0}个地点`} · ${m.projects===null?'全部项目':`${m.projects?.length||0}个项目`}`:''}</small></span>${mgr&&m.role!=='owner'&&m.userId!==T.user.id?button('权限','team-member',false,`data-id="${m.userId}"`):''}</div>`).join('')}<div class="modal-actions">${button('输入邀请码','team-join')}${button('申请加入其他库','team-request')}</div></section>
  <section class="panel"><div class="panel-head"><h2>敏感操作审批</h2>${currentRole==='owner'?button(w.policy.approvals?'关闭审批':'开启审批','team-policy'):''}</div><p class="helper">${w.policy.approvals?'已开启：盘点、损耗、撤销、恢复需另一位管理员批准。':'尚未开启。开启前需要至少两位管理员；个人库可直接记账。'}</p>${t.approvals.slice().reverse().map(p=>`<div class="list-row"><span><b>${esc(p.username)} · ${esc(teamLabels[p.action.type]||p.action.type)} ${esc(p.action.kind||'')}</b><small>${statusName(p.status)} · ${time(p.at)}</small></span>${button('核对详情','team-approval-detail',false,`data-id="${p.id}"`)}</div>`).join('')||'<p class="helper">没有审批申请</p>'}</section>
  <section class="panel"><div class="panel-head"><h2>我的登录设备</h2></div><p class="helper">退出设备后，该设备再次联网时需重新登录。已经保存在离线设备上的快照无法远程擦除。</p>${t.devices.map(d=>`<div class="list-row"><span><b>${d.current?'当前设备':esc(d.device)}</b><small>登录 ${time(d.createdAt)} · 到期 ${time(d.expiresAt)}</small></span>${button('退出设备','team-device',false,`data-id="${d.id}"`)}</div>`).join('')}</section>
  ${mgr?`<section class="panel"><div class="panel-head"><h2>采购任务负责人</h2></div>${S.procurementItems.map(p=>`<div class="list-row"><span><b>${esc(part(p.partId)?.sku)}</b><small>负责人：${esc(p.assigneeName||'未分配')} · 已到货 ${p.receivedQty}/${p.orderedQty||p.requiredQty}${p.lastReceivedName?` · 最近确认 ${esc(p.lastReceivedName)}`:''}</small></span>${button('分配','team-assign',false,`data-id="${p.id}"`)}</div>`).join('')||'<p class="helper">先在采购清单中添加任务</p>'}</section>`:''}
  ${mgr?`<section class="panel"><div class="panel-head"><h2>邀请与加入申请</h2></div>${t.invites.map(i=>`<div class="list-row"><span><b>${roleName(i.role)}</b><small>${i.usedAt?'已使用':i.revokedAt?'已撤销':Date.parse(i.expiresAt)<Date.now()?'已过期':'等待使用'} · ${time(i.expiresAt)} 到期</small></span>${!i.usedAt&&!i.revokedAt?button('撤销','team-invite-revoke',false,`data-id="${i.id}"`):''}</div>`).join('')||'<p class="helper">没有邀请</p>'}${t.requests.map(r=>`<div class="list-row"><span><b>${esc(r.username)}</b><small>${esc(r.message)} · ${statusName(r.status)}</small></span>${r.status==='pending'?button('处理','team-request-review',false,`data-id="${r.id}"`):''}</div>`).join('')}</section>
  <section class="panel"><div class="panel-head"><h2>只读分享</h2>${button('生成链接','team-share')}</div><p class="helper">分享仅显示型号、参数与数量，不包含库位、成员、价格或流水。持有链接的人可查看。</p>${t.shares.map(s=>`<div class="list-row"><span>${s.revokedAt?'已撤销':'有效至 '+time(s.expiresAt)}</span>${!s.revokedAt?button('撤销','team-share-revoke',false,`data-id="${s.id}"`):''}</div>`).join('')}</section>
  <section class="panel"><div class="panel-head"><h2>库之间调拨</h2>${button('新建调拨','team-transfer',true)}</div><p class="helper">需在来源库和目标库均为管理员，两端同一笔事务提交。启用审批的库暂不参与跨库调拨。</p>${t.transfers.slice(-10).reverse().map(x=>`<div class="list-row"><span><b>${esc(x.sku)} × ${x.qty}</b><small>${esc(x.fromName)} → ${esc(x.toName)} · ${esc(x.username)}</small></span><small>${time(x.at)}</small></div>`).join('')}</section>`:''}</div>
  <section class="panel"><div class="panel-head"><h2>操作审计</h2><small>显示最近300条${mgr?'':'本人'}记录</small></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>结果</th></tr></thead><tbody>${t.audit.map(x=>`<tr><td>${time(x.at)}</td><td>${esc(x.username)}</td><td>${esc(teamLabels[x.action]||x.action)}</td><td>${x.detail?.rev?'库存版本 '+x.detail.rev:''}${esc(x.detail?.kind||'')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function teamSettingsView(){return `${header('设置与备份','当前库的设置',esc(T.workspaces.find(x=>x.id===space)?.name||''),button('成员与协作','team-open'))}<div class="team-grid">${teamLibrarySettings()}<section class="panel"><div class="panel-head"><h2>库级备份与旧数据迁移</h2></div><p>JSON备份包含当前库的物料、库存、BOM项目和流水。恢复保留当前库成员及权限；恢复前自动保存一份库存备份。</p>${teamManager()?`<div class="modal-actions">${button('下载当前库备份','backup',true)}${button('保存库内备份','team-backup-save')}<label class="btn btn-secondary">导入 / 恢复JSON<input id="restoreInput" type="file" accept=".json" hidden></label>${isLocal&&currentRole==='owner'?button('预览并迁移旧版库存','team-migrate'):''}</div>${button('查看库内备份','team-backups')}`:'<p class="helper">下载完整库备份和恢复需要管理员权限。物料表可在元件库按你的范围导出。</p>'}</section><section class="panel"><div class="panel-head"><h2>本地联机试用</h2></div><p>电脑运行多人测试版时，手机或另一台电脑访问下面的地址并注册自己的账号，通过邀请码加入共享库。</p>${button('显示连接地址','team-connection')}${button('修改服务器地址','team-server')}<div id="teamConnection"></div><p class="helper">当前阶段数据保存在这台电脑。电脑关机后可查看已同步快照，联网提交仍需电脑服务运行。</p><a class="btn btn-secondary" href="/downloads/component-hub.apk">下载多人测试版 APK</a></section><section class="panel"><div class="panel-head"><h2>库名称</h2></div>${teamManager()?tform('rename',field('库名称','name',T.workspaces.find(x=>x.id===space)?.name||'',{required:true}),'保存名称'):''}</section><section class="panel"><div class="panel-head"><h2>价格关注</h2></div>${teamManager()?tform('price-settings',field('涨价提醒阈值 %','priceThreshold',S.settings.priceThreshold,{type:'number',min:0.1,step:0.1}),'保存阈值'):''}<p>采购默认跳转立创商城；厂商资料使用官方链接。管理员可在关注页手动刷新已填写立创编号的报价。</p><p class="helper">本地多人测试阶段的自定义厂商数据源尚未接入。</p></section></div>`;}
async function teamPost(a){if(!T.team)await teamLoad();const r=await api('team/action',{method:'POST',body:{...a,revision:T.team.revision}});T.team=null;await refreshIdentity();return r;}
async function showTransferForm(destId){const allowed=T.workspaces.filter(w=>w.id!==space&&['owner','admin'].includes(w.role));if(!allowed.length)throw new Error('请先创建或加入另一个你能管理的元件库');const target=allowed.find(x=>x.id===destId)||allowed[0];const r=await api('state',{workspace:target.id});openModal('核对跨库调拨',tform('transfer',`${selectField('来源库位','stockId',S.stocks.filter(x=>x.qty>0).map(x=>({value:x.id,label:stockName(x)})),S.stocks.find(x=>x.qty>0)?.id)}<div class="field"><label>目标库</label><select id="teamTransferTo" name="toLibraryId">${allowed.map(w=>`<option value="${w.id}" ${w.id===target.id?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div>${selectField('目标地点','locationId',r.state.locations.map(x=>({value:x.id,label:x.name})),r.state.locations[0]?.id)}${field('目标库位','bin')}${field('调拨数量','qty',1,{type:'number',min:1,required:true})}${field('备注','note')}<p class="note-box">确认后同时减少来源库并增加目标库。目标无此元件会自动建档；同型号参数不同会整单拒绝。</p>`,'确认两端调拨'),{type:'team-transfer',toRev:r.state.rev,requestId:uid()});}
async function teamActionUI(el){const a=el.dataset.act,id=el.dataset.id;if(a==='team-server'){if(window.AndroidDownloads?.changeServer)window.AndroidDownloads.changeServer();else toast('请在浏览器地址栏打开电脑服务的新地址');return;}if(!T.user){showAuthScreen();return;}
  if(a==='workspace-manage'||a==='team-switch'){await refreshIdentity();openModal('我的元件库',`<p>${esc(T.user.username)} · 一个账号可加入多个独立库</p>${T.workspaces.map(w=>`<button class="list-row" data-act="team-select" data-id="${w.id}"><span><b>${esc(w.name)}</b><small>${roleName(w.role)}</small></span>${w.id===space?'当前':''}</button>`).join('')}<div class="modal-actions">${button('新建库','team-create',true)}${button('邀请码加入','team-join')}${button('申请加入','team-request')}${button('退出账号','team-logout')}</div>`);return;}
  if(a==='team-select'){await switchWorkspace(id);setView('dashboard');return;}
  if(a==='team-open'){setView('team');return;}
  if(a==='team-refresh'){await refreshIdentity();await load();await teamLoad();render();return;}
  if(a==='team-logout'){await api('auth/logout',{method:'POST',auth:true});clearIdentity();showAuthScreen('已退出账号，本设备已清除该账号的离线库存及草稿');return;}
  if(a==='team-copy-id'){try{await navigator.clipboard.writeText(space);toast('库编号已复制');}catch{openModal('复制库编号',`<p>长按或选中以下编号复制：</p><input readonly class="invite-code" value="${esc(space)}">`);}return;}
  if(a==='team-create'||a==='team-join'||a==='team-request'){await teamLoad();openModal(a==='team-create'?'新建独立元件库':a==='team-join'?'邀请码加入':'申请加入元件库',tform(a.slice(5),a==='team-create'?field('元件库名称','name','',{required:true}):a==='team-join'?field('一次性邀请码','code','',{required:true}):field('库编号（由管理员提供）','libraryId','',{required:true})+field('申请说明','message'),'提交'));return;}
  if(a==='team-invite'){await teamLoad();openModal('邀请成员',tform('invite',selectField('角色','role',[{value:'member',label:'可出入库成员'},{value:'readonly',label:'只读成员'},...(currentRole==='owner'?[{value:'admin',label:'管理员'}]:[])],'member')+field('有效天数（1～30）','days',7,{type:'number',min:1})+scopeFields(),'生成一次性邀请码'));return;}
  if(a==='team-member'){await teamLoad();const m=T.team.members.find(x=>x.userId===id);openModal('调整 '+m.username+' 的权限',tform('member',selectField('角色','role',[{value:'member',label:'可出入库成员'},{value:'readonly',label:'只读成员'},...(currentRole==='owner'?[{value:'admin',label:'管理员'}]:[])],m.role)+scopeFields(m),'保存权限')+button('移除此成员','team-remove-confirm',false,`data-id="${id}"`),{userId:id});return;}
  if(a==='team-approval-detail'){await teamLoad();const p=T.team.approvals.find(x=>x.id===id);openModal('审批核对',`<p>${esc(p.username)} · ${esc(teamLabels[p.action.type]||p.action.type)} ${esc(p.action.kind||'')} · ${statusName(p.status)}</p><p>申请基于库存版本 ${p.action.rev}。${esc(p.action.note||'')}</p>${p.action.backup?`<p>替换为备份中的 ${p.action.backup.parts} 种元件、${p.action.backup.stocks} 个库位。</p>`:''}<div class="table-scroll"><table><thead><tr><th>元件</th><th>地点 / 库位</th><th>原数量</th><th>提交后</th></tr></thead><tbody>${(p.preview||[]).map(x=>`<tr><td>${esc(x.sku)}</td><td>${esc(x.location)} / ${esc(x.bin)}</td><td>${x.before}</td><td>${x.after}</td></tr>`).join('')}</tbody></table></div>${p.status==='pending'&&teamManager()&&p.userId!==T.user.id?`<div class="modal-actions">${button('批准并提交','team-approve',true,`data-id="${id}" data-decision="approve"`)}${button('驳回','team-approve',false,`data-id="${id}" data-decision="reject"`)}</div>`:''}`);return;}
  if(a==='team-approve'){await api('approve',{method:'POST',body:{id,decision:el.dataset.decision}});closeModal();await load();await teamLoad();render();toast('审批已处理');return;}
  if(a==='team-policy'){await teamLoad();const enabled=T.team.workspace.policy.approvals;openModal('确认审批规则',tform('policy',`<p>${enabled?'关闭后有权限的成员可以直接提交敏感操作。':'开启后，盘点、损耗、撤销和恢复库存必须由另一位管理员核对批准。跨库调拨暂时停用。'}</p><input type="hidden" name="enabled" value="${!enabled}">`,'确认'));return;}
  if(['team-device','team-invite-revoke','team-share-revoke','team-remove-confirm'].includes(a)){await teamLoad();const types={'team-device':'device.revoke','team-invite-revoke':'invite.revoke','team-share-revoke':'share.revoke','team-remove-confirm':'member.remove'};openModal('确认操作',tform('confirm',`<p>${a==='team-device'?'该设备将被退出，重新使用需要登录。':a==='team-remove-confirm'?'此成员将无法再访问该库。':'此邀请或分享将立即失效。'}</p>`,'确认'),{teamOperation:{type:types[a],id,userId:id}});return;}
  if(a==='team-request-review'){await teamLoad();const r=T.team.requests.find(x=>x.id===id);openModal('处理 '+r.username+' 的加入申请',tform('request-review',selectField('处理结果','decision',[{value:'approve',label:'批准加入'},{value:'reject',label:'驳回'}],'approve')+selectField('角色','role',[{value:'member',label:'可出入库成员'},{value:'readonly',label:'只读成员'}],'readonly')+scopeFields()),{requestId:id});return;}
  if(a==='team-share'){await teamLoad();openModal('创建只读分享',tform('share',field('有效天数（1～30）','days',7,{type:'number',min:1})+'<p class="note-box">链接接收人可以查看当前型号与数量，不需要账号。到期自动失效，也可随时撤销。</p>','生成链接'));return;}
  if(a==='team-assign'){await teamLoad();const item=S.procurementItems.find(x=>x.id===id);openModal('分配采购负责人',tform('assign',selectField('负责人','userId',T.team.members.filter(x=>x.role!=='readonly').map(x=>({value:x.userId,label:x.username})),item.assigneeId)),{itemId:id});return;}
  if(a==='team-backup-save'){await teamLoad();await teamPost({type:'backup.create'});toast('当前库备份已保存');return;}
  if(a==='team-backups'){await teamLoad();openModal('库内最近10份备份',T.team.backups.slice().reverse().map(b=>`<div class="list-row"><span>${time(b.createdAt)} · ${esc(b.reason)}<small>${b.parts}种 · 库存版本${b.rev}</small></span>${button('核对恢复','team-backup-review',false,`data-id="${b.id}"`)}</div>`).join('')||'<p>暂无库内备份</p>');return;}
  if(a==='team-backup-review'){const backup=await api('backup?id='+encodeURIComponent(id));await restorePreview(new File([JSON.stringify(backup)],'库内备份.json',{type:'application/json'}));return;}
  if(a==='team-migrate'){const r=await api('legacy/preview');openModal('核对旧版库存迁移',tform('migrate',`<p>旧版库存共 <b>${r.parts}</b> 种元件、${r.stocks} 个库位、${r.orders} 笔流水、${num(r.quantity)} 个库存。</p><p>确认后复制到当前空库「${esc(T.workspaces.find(x=>x.id===space)?.name)}」，原来的单人库存文件保留。</p>`,'确认迁移'),{digest:r.digest});return;}
  if(a==='team-connection'){const r=await api('connection');$('#teamConnection').innerHTML=r.addresses.map(x=>`<p>${esc(x.name)}<input readonly value="${esc(x.url)}"></p>`).join('')||'<p>尚未发现可用局域网地址</p>';return;}
  if(a==='team-server'){if(window.AndroidDownloads?.changeServer)window.AndroidDownloads.changeServer();else toast('电脑浏览器请直接打开新的服务地址；APK可在首次打开时设置地址');return;}
  if(a==='team-transfer'){await showTransferForm();return;}
}
async function teamSubmit(e){const f=e.target,submit=e.submitter||f.querySelector('[type="submit"]');if(submit?.disabled)return;if(submit)submit.disabled=true;const fd=new FormData(f),d=Object.fromEntries(fd),kind=f.dataset.teamForm,ctx={...modalContext};try{
  if(kind==='account'){const r=await api('auth/'+(d.mode==='register'?'register':'login'),{method:'POST',auth:true,body:{username:d.username,password:d.password,device:/ComponentHubAndroid/.test(navigator.userAgent)?'Android APK':navigator.userAgent}});T.user=r.user;T.workspaces=r.workspaces;T.epoch++;resetWorkspaceState();space=r.workspaces[0].id;sessionStorage.setItem('component-space',space);localStorage.setItem('team-last-user',JSON.stringify({user:T.user,workspaces:T.workspaces,space}));await load();connectEvents();return;}
  if(kind==='create'||kind==='join'){const r=await teamPost(kind==='create'?{type:'library.create',name:d.name}:{type:'invite.join',code:d.code});await switchWorkspace(r.workspaceId);setView('dashboard');return;}
  if(kind==='invite'){const r=await teamPost({type:'invite.create',role:d.role,days:Number(d.days),...scopeData(fd)});openModal('邀请码已生成',`<p>有效期 ${d.days} 天，仅可使用一次。复制给要邀请的人：</p><input class="invite-code" readonly value="${esc(r.code)}"><p>对方注册自己的账号后，在“切换库 → 邀请码加入”输入。邀请码只在本次生成时显示。</p>`);return;}
  if(kind==='share'){let origin=location.origin;if(isLocal){const c=await api('connection'),address=c.addresses.find(x=>/WLAN|Wi-Fi|Ethernet|以太网/i.test(x.name))||c.addresses[0];if(address)origin=address.url.replace(/\/$/,'');}const r=await teamPost({type:'share.create',days:Number(d.days)});openModal('只读链接',`<p>复制以下链接；本地试用时接收人需要能连接这台电脑：</p><textarea readonly rows="4">${esc(origin+'/#share='+r.shareKey)}</textarea>`);return;}
  if(kind==='member')await teamPost({type:'member.save',userId:ctx.userId,role:d.role,...scopeData(fd)});
  else if(kind==='price-settings')await mutate({type:'settings.save',...S.settings,priceThreshold:Number(d.priceThreshold),feedEnabled:false,lcscEnabled:false});
  else if(kind==='policy')await teamPost({type:'policy.save',approvals:d.enabled==='true'});
  else if(kind==='confirm'){const r=await teamPost(ctx.teamOperation);if(r.loggedOut){clearIdentity();showAuthScreen('当前设备已退出');return;}}
  else if(kind==='request')await teamPost({type:'join.request',libraryId:d.libraryId,message:d.message});
  else if(kind==='request-review')await teamPost({type:'request.review',id:ctx.requestId,decision:d.decision,role:d.role,...scopeData(fd)});
  else if(kind==='assign')await teamPost({type:'procurement.assign',itemId:ctx.itemId,userId:d.userId});
  else if(kind==='rename'){await teamLoad();await teamPost({type:'library.rename',name:d.name});}
  else if(kind==='migrate'){const r=await api('legacy/import',{method:'POST',body:{digest:ctx.digest}});acceptState(r.state);}
  else if(kind==='transfer')await api('transfer',{method:'POST',body:{...d,qty:Number(d.qty),toRev:ctx.toRev,rev:S.rev,requestId:ctx.requestId}});
  closeModal();await load();await teamLoad();render();toast('已保存');
 }catch(err){if(err.status===409){await teamLoad().catch(()=>{});f.dataset.requestId='';}if($('#dialog').open)errorInModal(err.message);else toast(err.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}}
document.addEventListener('change',e=>{if(e.target.id==='teamTransferTo')showTransferForm(e.target.value).catch(e=>errorInModal(e.message));});
function applyRoleUI(){if(!S)return;const readonly=currentRole==='readonly';document.body.dataset.role=currentRole;const writes=new Set(['add-part','edit-part','in','out','watch-add','bom-submit','bom-confirm','bom-post','inventory-bulk-out','bulk-out','project-new','project-edit','project-reserve','project-release','project-issue','project-procure','purchase-new','purchase-edit','purchase-receive','container-new','container-assign','container-stocktake','finished-new','draft-submit']);if(readonly)$$('[data-act]').forEach(x=>{if(writes.has(x.dataset.act)){x.disabled=true;x.title='只读成员无此操作权限';}});if(S.access?.restricted){const h=$('#page .page-head');if(h)h.insertAdjacentHTML('afterend','<p class="notice-info">当前仅显示你有权限的地点和项目；库存数量和导出范围以此为准。</p>');}}

function teamLibrarySettings(){return `<section class="panel"><div class="panel-head"><h2>存放地点</h2>${teamManager()?button("添加地点","location-new"):""}</div>${S.locations.map(l=>`<div class="list-row"><span><b>${esc(l.name)}</b><small>${S.stocks.filter(x=>x.locationId===l.id).length} 个库位</small></span>${teamManager()?button("编辑","location-edit",false,`data-id="${l.id}"`):""}</div>`).join("")}</section>`;}
function reservationOwners(projectId){return [...new Set((S.reservations||[]).filter(x=>x.projectId===projectId).map(x=>x.ownerName||"旧版记录"))].join("、");}

initialize();
